" for=\"select-qdcb-detail-format\">Định dạng kết quả:</label>\n                  <select id=\"select-qdcb-detail-format\" class=\"form-select\">\n                    <option value=\"markdown\" selected>Markdown (Trực quan kèm danh sách TTHC)</option>\n                    <option value=\"json\">JSON (Dữ liệu thô chi tiết)</option>\n                  </select>\n                </div>\n              </div>\n\n              <div class=\"quick-chips\">\n                <span class=\"chip-label\">Mẫu chi tiết QĐCB:</span>\n                <button type=\"button\" class=\"btn-chip\" data-fill-qdcb-detail=\"807/QĐ-TTCP\">807/QĐ-TTCP (Thanh tra CP)</button>\n                <button type=\"button\" class=\"btn-chip\" data-fill-qdcb-detail=\"4045/QĐ-UBND\">4045/QĐ-UBND (Khánh Hòa)</button>\n              </div>\n            </div>\n\n            <!-- Pagination options -->\n            <div class=\"pagination-row\" id=\"common-pagination-controls\">\n              <div class=\"pagination-field\">\n                <label for=\"input-limit\">Số lượng (Limit):</label>\n                <select id=\"input-limit\" class=\"form-select-sm\">\n                  <option value=\"5\">5</option>\n                  <option value=\"10\" selected>10</option>\n                  <option value=\"20\">20</option>\n                  <option value=\"50\">50</option>\n                </select>\n              </div>\n              <div class=\"pagination-field\">\n                <label for=\"input-page\">Trang (Page):</label>\n                <input type=\"number\" id=\"input-page\" class=\"form-input-sm\" value=\"1\" min=\"1\" max=\"100\">\n              </div>\n            </div>\n\n            <!-- Submit Button -->\n            <div class=\"action-buttons-group\">\n              <button type=\"submit\" class=\"btn btn-primary btn-block\" id=\"btn-execute-tool\">\n                <span class=\"btn-spinner\" id=\"execute-spinner\" style=\"display: none;\"></span>\n                <span id=\"btn-execute-text\"><i class=\"bi bi-play-circle-fill\"></i> Gọi MCP Tool Call</span>\n              </button>\n            </div>\n          </form>\n        </div>\n\n        <!-- Right: Execution Result Display -->\n        <div class=\"result-display-card glass-card\">\n          <div class=\"result-header\">\n            <div class=\"result-title-group\">\n              <h2 class=\"section-title\">\n                <i class=\"bi bi-clipboard-data-fill\"></i> Kết Quả Tool Execution\n              </h2>\n              <span class=\"execution-time-badge\" id=\"execution-time\" style=\"display: none;\">0ms</span>\n            </div>\n\n            <div class=\"view-toggle-group\">\n              <button class=\"toggle-btn active\" id=\"btn-view-rendered\">Giao Diện</button>\n              <button class=\"toggle-btn\" id=\"btn-view-markdown\">Markdown</button>\n              <button class=\"toggle-btn\" id=\"btn-view-json\">JSON-RPC</button>\n              <button class=\"btn btn-secondary btn-xs\" id=\"btn-copy-result\" title=\"Sao chép kết quả\">\n                <i class=\"bi bi-clipboard\"></i> Copy\n              </button>\n            </div>\n          </div>\n\n          <!-- Result Viewports -->\n          <div class=\"result-viewport-container\">\n            <!-- Rendered View -->\n            <div class=\"viewport\" id=\"viewport-rendered\">\n              <div class=\"empty-state\">\n                <div class=\"empty-icon\"><i class=\"bi bi-cpu\"></i></div>\n                <h3>Sẵn sàng thực thi MCP Tool</h3>\n                <p>Chọn tool ở cột bên trái và nhấn <b>\"Gọi MCP Tool Call\"</b> để tra cứu dữ liệu trực tiếp từ MCP server.</p>\n              </div>\n            </div>\n\n            <!-- Markdown View -->\n            <pre class=\"viewport-code\" id=\"viewport-markdown\" style=\"display: none;\"><code>// Kết quả định dạng Markdown hiển thị ở đây...</code></pre>\n\n            <!-- Raw JSON-RPC View -->\n            <pre class=\"viewport-code\" id=\"viewport-json\" style=\"display: none;\"><code>// Kết quả phản hồi giao thức JSON-RPC 2.0 hiển thị ở đây...</code></pre>\n          </div>\n        </div>\n\n      </div>\n    </section>\n\n    <!-- TAB 2: CONNECT GUIDES -->\n    <section class=\"tab-panel\" id=\"panel-connect\">\n      <div class=\"glass-card mb-4\">\n        <h2 class=\"section-title\">\n          <i class=\"bi bi-plug-fill\"></i> Hướng Dẫn Tích Hợp MCP Client\n        </h2>\n        <p class=\"section-desc\">\n          Server MCP TTHC hỗ trợ cả hai giao thức: <b>SSE (Server-Sent Events)</b> và <b>Direct HTTP JSON-RPC</b>. Bạn có thể kết nối ngay với Claude Desktop, Cursor AI, Windsurf, v.v.\n        </p>\n\n        <div class=\"client-tabs\">\n          <button class=\"client-tab active\" data-client=\"cursor\">Cursor AI (.cursor/mcp.json)</button>\n          <button class=\"client-tab\" data-client=\"claude\">Claude Desktop</button>\n          <button class=\"client-tab\" data-client=\"windsurf\">Windsurf IDE</button>\n          <button class=\"client-tab\" data-client=\"openai\">OpenAI Plugin (ChatGPT)</button>\n          <button class=\"client-tab\" data-client=\"openapi\">OpenAPI Schema (Custom GPT / Dify)</button>\n          <button class=\"client-tab\" data-client=\"curl\">cURL / HTTP Test</button>\n        </div>\n\n        <div class=\"code-box-wrapper\">\n          <div class=\"code-box-header\">\n            <span class=\"file-label\" id=\"config-file-label\">.cursor/mcp.json</span>\n            <button class=\"btn btn-secondary btn-xs\" id=\"btn-copy-config\">\n              <i class=\"bi bi-clipboard\"></i> Sao chép cấu hình\n            </button>\n          </div>\n          <pre class=\"code-box\"><code id=\"config-code-display\">// Đang tạo mã cấu hình...</code></pre>\n        </div>\n      </div>\n    </section>\n\n    <!-- TAB 3: TOOL REFERENCE -->\n    <section class=\"tab-panel\" id=\"panel-docs\">\n      <div class=\"glass-card\">\n        <div class=\"panel-header-row\" style=\"display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 12px; margin-bottom: 20px;\">\n          <div>\n            <h2 class=\"section-title\">\n              <i class=\"bi bi-journal-code\"></i> Danh Sách Tools & Schemas MCP\n            </h2>\n            <p class=\"section-desc\" style=\"margin-bottom: 0;\">\n              Toàn bộ 14 công cụ MCP chuẩn hóa hỗ trợ tra cứu, trích xuất dữ liệu và tích hợp trợ lý AI thông minh:\n            </p>\n          </div>\n          <a href=\"/openapi.json\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-sm\" style=\"display: inline-flex; align-items: center; gap: 6px;\">\n            <i class=\"bi bi-filetype-json\"></i> OpenAPI 3.1.0 Schema\n          </a>\n        </div>\n\n        <!-- Modern Toolbar: Search & Category Filter -->\n        <div class=\"docs-toolbar\">\n          <div class=\"docs-search-row\">\n            <div class=\"docs-search-box\">\n              <i class=\"bi bi-search search-icon\"></i>\n              <input type=\"text\" id=\"input-search-tools\" placeholder=\"Tìm kiếm công cụ theo tên tool, alias, từ khóa, tham số (ví dụ: gia_lai, noi_bo, ho_so, ma_tthc)...\">\n              <button type=\"button\" class=\"btn-clear-tool-search\" id=\"btn-clear-tool-search\" title=\"Xóa tìm kiếm\" style=\"display: none;\">\n                <i class=\"bi bi-x-circle-fill\"></i>\n              </button>\n            </div>\n          </div>\n          <div class=\"docs-filter-chips\">\n            <span class=\"filter-chip-label\"><i class=\"bi bi-funnel\"></i> Phân loại:</span>\n            <button type=\"button\" class=\"filter-chip active\" data-filter=\"all\">Tất cả (14)</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"dvctt\">DVCTT Trực Tuyến</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"chuyen_sau\">Chuyên sâu</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"tra_cuu\">Tra cứu</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"bo_loc\">Bộ lọc</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"goi_y\">Gợi ý sự kiện</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"openai\">Chuẩn OpenAI</button>\n            <button type=\"button\" class=\"filter-chip\" data-filter=\"he_thong\">Hệ thống</button>\n          </div>\n        </div>\n\n        <div class=\"tools-grid\" id=\"tools-doc-grid\">\n\n          <!-- TOOL QĐCB 1: tra_cuu_quyet_dinh_cong_bo -->\n          <div class=\"tool-doc-card\" data-tool=\"tra_cuu_quyet_dinh_cong_bo\" data-category=\"tra_cuu chuyen_sau\" style=\"--card-glow: rgba(245, 158, 11, 0.25); --accent-line: #f59e0b;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #f59e0b; background: rgba(245, 158, 11, 0.12); border-color: rgba(245, 158, 11, 0.28);\">\n                  <i class=\"bi bi-file-earmark-check-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tra_cuu_quyet_dinh_cong_bo</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tra_cuu_quyet_dinh_cong_bo\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">tra_cuu_qdcb</span>\n                    <span class=\"alias-code\">tim_kiem_qdcb</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge\" style=\"background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.3);\"><i class=\"bi bi-dot\"></i> QĐCB DVCQG</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Tra cứu danh mục Quyết định công bố (QĐCB) TTHC trên toàn quốc từ nguồn <code>Crawler-TTHC/qdcb</code> (~2,000 QĐCB cấp Bộ, Tỉnh). Hỗ trợ tìm theo từ khóa trích yếu, số quyết định, cơ quan ban hành, lĩnh vực, năm/tháng hoặc lấy nhanh QĐCB mới ban hành trong tháng.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">10 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa tìm kiếm trong trích yếu, số quyết định, cơ quan hoặc lĩnh vực QĐCB.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">so_quyet_dinh</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Số Quyết định công bố (vd: <code>807/QĐ-TTCP</code>, <code>4045/QĐ-UBND</code>).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">co_quan_ban_hanh</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Cơ quan ban hành quyết định (vd: <code>Thanh tra Chính phủ</code>, <code>UBND tỉnh Gia Lai</code>).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">linh_vuc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Lĩnh vực quản lý của QĐCB (vd: <code>Hộ tịch</code>, <code>Đất đai</code>).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">nam</code> / <code class=\"param-name\">thang</code>\n                    <span class=\"param-type\">number | string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Lọc theo năm (vd: <code>2026</code>) hoặc tháng <code>YYYY-MM</code> (vd: <code>2026-11</code>).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">moi_trong_thang</code>\n                    <span class=\"param-type\">boolean</span>\n                    <span class=\"param-req optional\">mặc định: false</span>\n                  </div>\n                  <div class=\"param-desc\"><code>true</code> để lấy nhanh danh sách QĐCB mới ban hành trong tháng hiện tại.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">limit</code> / <code class=\"param-name\">page</code> / <code class=\"param-name\">dinh_dang</code>\n                    <span class=\"param-type\">number | enum</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Phân trang (1-50, trang mặc định 1) và định dạng <code>markdown</code> | <code>json</code>.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tra_cuu_quyet_dinh_cong_bo\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-hdd-network\"></i> GET /api/qdcb/search</span>\n            </div>\n          </div>\n\n          <!-- TOOL QĐCB 2: chi_tiet_quyet_dinh_cong_bo -->\n          <div class=\"tool-doc-card\" data-tool=\"chi_tiet_quyet_dinh_cong_bo\" data-category=\"tra_cuu chuyen_sau\" style=\"--card-glow: rgba(16, 185, 129, 0.25); --accent-line: #10b981;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #10b981; background: rgba(16, 185, 129, 0.12); border-color: rgba(16, 185, 129, 0.28);\">\n                  <i class=\"bi bi-journal-text\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">chi_tiet_quyet_dinh_cong_bo</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"chi_tiet_quyet_dinh_cong_bo\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">chi_tiet_qdcb</span>\n                    <span class=\"alias-code\">lay_qdcb_theo_so</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge\" style=\"background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.3);\"><i class=\"bi bi-dot\"></i> Chi tiết QĐCB</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Lấy thông tin chi tiết toàn văn một Quyết định công bố theo Số QĐ hoặc UUID chuẩn cấu trúc Cổng DVCQG, bao gồm trích yếu, ngày hiệu lực, tệp đính kèm và toàn bộ danh sách TTHC kèm theo (Công bố mới, Sửa đổi bổ sung, Bãi bỏ, Thay thế).\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">2 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">so_hoac_id_qdcb</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Số Quyết định công bố (vd: <code>807/QĐ-TTCP</code>) hoặc UUID định danh QĐCB.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">dinh_dang</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: markdown</span>\n                  </div>\n                  <div class=\"param-desc\">Định dạng kết quả: <code>markdown</code> (trực quan kèm bảng TTHC) hoặc <code>json</code>.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"chi_tiet_quyet_dinh_cong_bo\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-hdd-network\"></i> GET /api/qdcb/detail</span>\n            </div>\n          </div>\n          \n          <!-- TOOL 1: tra_cuu_tthc_gia_lai -->\n          <div class=\"tool-doc-card\" data-tool=\"tra_cuu_tthc_gia_lai\" data-category=\"chuyen_sau\" style=\"--card-glow: rgba(56, 189, 248, 0.25); --accent-line: #38bdf8;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #38bdf8; background: rgba(56, 189, 248, 0.12); border-color: rgba(56, 189, 248, 0.28);\">\n                  <i class=\"bi bi-geo-alt-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tra_cuu_tthc_gia_lai</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tra_cuu_tthc_gia_lai\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">tthc_gia_lai</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-warning\"><i class=\"bi bi-dot\"></i> Tỉnh Gia Lai</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Tra cứu chuyên sâu các Thủ tục Hành chính thuộc tỉnh Gia Lai. Bao gồm cấp tỉnh, cấp xã, các Sở ngành (Xây dựng, Nông nghiệp, Tài chính...), Hệ thống Chi nhánh VPĐKĐĐ (Pleiku, Chư Sê, Đak Đoa, An Khê, Ayun Pa, Kbang...), Ban Quản lý Khu kinh tế, Chủ tịch UBND tỉnh...\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">5 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Tìm theo tên, mã hoặc nội dung nghiệp vụ.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">ma_tthc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Mã TTHC thuộc tỉnh Gia Lai để xem chi tiết ngay.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">cap_thuc_hien</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: tat_ca</span>\n                  </div>\n                  <div class=\"param-desc\"><code>tat_ca</code>, <code>cap_tinh</code>, <code>cap_xa</code>, <code>cap_xa_va_tinh</code>.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">co_quan_thuc_hien</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Lọc theo cơ quan (Sở ngành, VPĐKĐĐ Pleiku, Chư Sê, UBND cấp xã...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">chi_tiet</code>\n                    <span class=\"param-type\">boolean</span>\n                    <span class=\"param-req optional\">mặc định: false</span>\n                  </div>\n                  <div class=\"param-desc\"><code>true</code> để trích xuất đầy đủ hồ sơ, trình tự, căn cứ pháp lý.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tra_cuu_tthc_gia_lai\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 2: tra_cuu_tthc_noi_bo -->\n          <div class=\"tool-doc-card\" data-tool=\"tra_cuu_tthc_noi_bo\" data-category=\"chuyen_sau\" style=\"--card-glow: rgba(168, 85, 247, 0.25); --accent-line: #c084fc;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #c084fc; background: rgba(168, 85, 247, 0.12); border-color: rgba(168, 85, 247, 0.28);\">\n                  <i class=\"bi bi-diagram-3-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tra_cuu_tthc_noi_bo</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tra_cuu_tthc_noi_bo\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">tthc_noi_bo</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge\" style=\"background: rgba(168, 85, 247, 0.18); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.35);\"><i class=\"bi bi-dot\"></i> TTHC Nội Bộ</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Tra cứu chuyên sâu các Thủ tục Hành chính nội bộ trong hệ thống hành chính nhà nước. Gồm 2 nhóm: TTHC giữa các cơ quan hành chính nhà nước (liên thông, đa cơ quan/cấp) và TTHC nội bộ trong từng cơ quan (Bộ ngành, UBND cấp tỉnh, Sở ban ngành...).\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">7 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa tìm kiếm theo tên, mã hoặc nội dung nghiệp vụ nội bộ.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">ma_tthc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Mã TTHC nội bộ cụ thể (ví dụ: <code>6.006791</code>, <code>5.003975</code>) để xem chi tiết.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">co_quan</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Cơ quan thực hiện hoặc công bố (Bộ Nội vụ, Bộ Công thương, UBND tỉnh...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">linh_vuc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Lĩnh vực nội bộ (Khoáng sản, Thi đua khen thưởng, Công chức...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">cap_thuc_hien</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: tat_ca</span>\n                  </div>\n                  <div class=\"param-desc\"><code>tat_ca</code>, <code>cap_bo</code>, <code>cap_tinh</code>, <code>cap_xa</code>.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">nhom_noi_bo</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: tat_ca</span>\n                  </div>\n                  <div class=\"param-desc\"><code>tat_ca</code>, <code>giua_cac_co_quan</code>, <code>trong_noi_bo</code>.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">chi_tiet</code>\n                    <span class=\"param-type\">boolean</span>\n                    <span class=\"param-req optional\">mặc định: false</span>\n                  </div>\n                  <div class=\"param-desc\"><code>true</code> để xem chi tiết đầy đủ hồ sơ, trình tự từng bước.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tra_cuu_tthc_noi_bo\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL: tra_cuu_tthc_noi_bo_gia_lai -->\n          <div class=\"tool-doc-card\" data-tool=\"tra_cuu_tthc_noi_bo_gia_lai\" data-category=\"chuyen_sau\" style=\"--card-glow: rgba(217, 70, 239, 0.25); --accent-line: #d946ef;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #e879f9; background: rgba(217, 70, 239, 0.12); border-color: rgba(217, 70, 239, 0.28);\">\n                  <i class=\"bi bi-building-gear\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tra_cuu_tthc_noi_bo_gia_lai</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tra_cuu_tthc_noi_bo_gia_lai\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">tthc_noi_bo_gia_lai</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge\" style=\"background: rgba(217, 70, 239, 0.18); color: #e879f9; border: 1px solid rgba(217, 70, 239, 0.35);\"><i class=\"bi bi-dot\"></i> TTHC Nội Bộ Gia Lai</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Tra cứu chuyên sâu các Thủ tục Hành chính Nội bộ thuộc phạm vi tỉnh Gia Lai. Bao gồm các thủ tục cấp tỉnh, cấp xã, UBND tỉnh Gia Lai, Chủ tịch UBND tỉnh, các Sở ban ngành địa phương theo Nghị định số 385/2026/NĐ-CP (Khoáng sản, Đất đai, Nội vụ, Tài chính...).\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">7 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa tìm kiếm TTHC nội bộ tỉnh Gia Lai theo tên hoặc nội dung nghiệp vụ.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">ma_tthc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Mã TTHC nội bộ cụ thể (ví dụ: <code>5.003972</code>, <code>5.003971</code>) để xem chi tiết.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">cap_thuc_hien</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: tat_ca</span>\n                  </div>\n                  <div class=\"param-desc\"><code>tat_ca</code>, <code>cap_tinh</code>, <code>cap_xa</code>.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">co_quan</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Cơ quan thực hiện tại Gia Lai (Chủ tịch UBND tỉnh, Sở TN&MT, UBND cấp xã...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">linh_vuc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Lĩnh vực nội bộ (Địa chất khoáng sản, Đất đai, Thi đua khen thưởng...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">nhom_noi_bo</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: tat_ca</span>\n                  </div>\n                  <div class=\"param-desc\"><code>tat_ca</code>, <code>giua_cac_co_quan</code>, <code>trong_noi_bo</code>.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">chi_tiet</code>\n                    <span class=\"param-type\">boolean</span>\n                    <span class=\"param-req optional\">mặc định: false</span>\n                  </div>\n                  <div class=\"param-desc\"><code>true</code> để xem chi tiết đầy đủ hồ sơ, trình tự từng bước.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tra_cuu_tthc_noi_bo_gia_lai\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 3: tra_cuu_theo_ma_tthc -->\n          <div class=\"tool-doc-card\" data-tool=\"tra_cuu_theo_ma_tthc\" data-category=\"tra_cuu\" style=\"--card-glow: rgba(6, 182, 212, 0.25); --accent-line: #06b6d4;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #06b6d4; background: rgba(6, 182, 212, 0.12); border-color: rgba(6, 182, 212, 0.28);\">\n                  <i class=\"bi bi-file-earmark-code-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tra_cuu_theo_ma_tthc</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tra_cuu_theo_ma_tthc\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">chi_tiet_tthc</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-primary\"><i class=\"bi bi-dot\"></i> Chi Tiết Chuyên Sâu</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Truy xuất toàn diện thông tin chi tiết chuyên sâu của TTHC theo mã (ví dụ: <code>6.006781</code>) hoặc tên thủ tục. Cho phép trích xuất từng phân mục độc lập và xuất định dạng Markdown hoặc JSON cấu trúc sạch cho AI Agent.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">3 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">ma_tthc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Mã TTHC (ví dụ <code>6.006781</code>) hoặc tên thủ tục.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">phan_muc</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: tat_ca</span>\n                  </div>\n                  <div class=\"param-desc\"><code>tat_ca</code>, <code>ho_so</code>, <code>trinh_tu</code>, <code>chi_phi</code>, <code>thoi_han</code>, <code>can_cu_phap_ly</code>.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">dinh_dang</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: markdown</span>\n                  </div>\n                  <div class=\"param-desc\"><code>markdown</code> (chuẩn đẹp) hoặc <code>json</code> (dữ liệu thô cho code).</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tra_cuu_theo_ma_tthc\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 4: tim_kiem_theo_ten_tthc -->\n          <div class=\"tool-doc-card\" data-tool=\"tim_kiem_theo_ten_tthc\" data-category=\"tra_cuu\" style=\"--card-glow: rgba(16, 185, 129, 0.25); --accent-line: #10b981;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #10b981; background: rgba(16, 185, 129, 0.12); border-color: rgba(16, 185, 129, 0.28);\">\n                  <i class=\"bi bi-search\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tim_kiem_theo_ten_tthc</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tim_kiem_theo_ten_tthc\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">tim_kiem_tthc</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-success\"><i class=\"bi bi-dot\"></i> Tìm Kiếm Tên</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Tìm kiếm danh sách TTHC theo tên hoặc từ khóa nội dung (hỗ trợ tiếng Việt có dấu hoặc không dấu, tự động chuẩn hóa dấu). Tốc độ phản hồi cực nhanh dưới 15ms.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">3 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">ten_tthc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa tên thủ tục (ví dụ: \"kết hôn\", \"hộ kinh doanh\", \"cấp phép\").</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">limit</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 10</span>\n                  </div>\n                  <div class=\"param-desc\">Số kết quả tối đa mỗi trang (1-50).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">page</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 1</span>\n                  </div>\n                  <div class=\"param-desc\">Trang kết quả cần hiển thị.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tim_kiem_theo_ten_tthc\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 5: loc_theo_cap_thuc_hien -->\n          <div class=\"tool-doc-card\" data-tool=\"loc_theo_cap_thuc_hien\" data-category=\"bo_loc\" style=\"--card-glow: rgba(59, 130, 246, 0.25); --accent-line: #3b82f6;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #3b82f6; background: rgba(59, 130, 246, 0.12); border-color: rgba(59, 130, 246, 0.28);\">\n                  <i class=\"bi bi-layers-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">loc_theo_cap_thuc_hien</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"loc_theo_cap_thuc_hien\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">loc_tthc_theo_cap</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-info\"><i class=\"bi bi-dot\"></i> Bộ Lọc Cấp</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Lọc danh sách thủ tục theo Cấp thực hiện (Cấp Bộ, Cấp tỉnh, Cấp xã, Cơ quan khác). Hỗ trợ kết hợp từ khóa lọc nâng cao và phân trang chuẩn.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">4 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">cap_thuc_hien</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Tên cấp thực hiện (ví dụ: \"Cấp Bộ\", \"Cấp tỉnh\", \"Cấp xã\").</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa kết hợp để thu hẹp kết quả trong cấp đó.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">limit</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 10</span>\n                  </div>\n                  <div class=\"param-desc\">Số lượng kết quả mỗi trang.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">page</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 1</span>\n                  </div>\n                  <div class=\"param-desc\">Trang cần xem.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"loc_theo_cap_thuc_hien\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 6: loc_theo_linh_vuc -->\n          <div class=\"tool-doc-card\" data-tool=\"loc_theo_linh_vuc\" data-category=\"bo_loc\" style=\"--card-glow: rgba(245, 158, 11, 0.25); --accent-line: #f59e0b;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #f59e0b; background: rgba(245, 158, 11, 0.12); border-color: rgba(245, 158, 11, 0.28);\">\n                  <i class=\"bi bi-tags-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">loc_theo_linh_vuc</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"loc_theo_linh_vuc\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">loc_tthc_theo_linh_vuc</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-warning\"><i class=\"bi bi-dot\"></i> Lĩnh Vực</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Lọc danh sách thủ tục theo Lĩnh vực thiết yếu (Hộ tịch, Thành lập kinh doanh, Đất đai, Xây dựng, Thuế, Hải quan, Đăng kiểm, Giao thông...).\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">4 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">linh_vuc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Tên lĩnh vực nghiệp vụ (ví dụ: <code>Đất đai</code>, <code>Hộ tịch</code>, <code>Xây dựng</code>).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa bổ sung để lọc hẹp trong lĩnh vực.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">limit</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 10</span>\n                  </div>\n                  <div class=\"param-desc\">Số lượng kết quả tối đa.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">page</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 1</span>\n                  </div>\n                  <div class=\"param-desc\">Trang kết quả.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"loc_theo_linh_vuc\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 7: tim_kiem_tong_hop -->\n          <div class=\"tool-doc-card\" data-tool=\"tim_kiem_tong_hop\" data-category=\"bo_loc\" style=\"--card-glow: rgba(139, 92, 246, 0.25); --accent-line: #8b5cf6;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #8b5cf6; background: rgba(139, 92, 246, 0.12); border-color: rgba(139, 92, 246, 0.28);\">\n                  <i class=\"bi bi-funnel-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">tim_kiem_tong_hop</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"tim_kiem_tong_hop\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">tra_cuu_nang_cao</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-purple\"><i class=\"bi bi-dot\"></i> Đa Tiêu Chí</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Tìm kiếm đa tiêu chí kết hợp từ khóa, lĩnh vực, cấp thực hiện, cơ quan thực hiện và lọc thủ tục có thu phí hay miễn phí giải quyết.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">7 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">tu_khoa</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa tìm kiếm theo tên hoặc nội dung.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">linh_vuc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Lĩnh vực nghiệp vụ cần lọc.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">cap_thuc_hien</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Cấp thực hiện (Cấp Bộ, Cấp tỉnh, Cấp xã...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">co_quan</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Cơ quan thực hiện (Bộ GTVT, Sở Y tế, UBND TP...).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">co_thu_phi</code>\n                    <span class=\"param-type\">boolean</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\"><code>true</code>: có phí; <code>false</code>: miễn phí.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tim_kiem_tong_hop\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 8: goi_y_thu_tuc_lien_quan -->\n          <div class=\"tool-doc-card\" data-tool=\"goi_y_thu_tuc_lien_quan\" data-category=\"goi_y\" style=\"--card-glow: rgba(20, 184, 166, 0.25); --accent-line: #14b8a6;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #14b8a6; background: rgba(20, 184, 166, 0.12); border-color: rgba(20, 184, 166, 0.28);\">\n                  <i class=\"bi bi-bezier2\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">goi_y_thu_tuc_lien_quan</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"goi_y_thu_tuc_lien_quan\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">thu_tuc_lien_quan</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-cyan\"><i class=\"bi bi-dot\"></i> Chuỗi Sự Kiện</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Gợi ý chuỗi thủ tục hành chính liên quan theo ngữ cảnh sự kiện đời sống & kinh doanh (sinh con, kết hôn, hộ kinh doanh, cư trú, y tế, mua bán nhà đất, thành lập doanh nghiệp...) hoặc liên thông cùng thủ tục gốc.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">4 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">ma_hoac_ten_tthc</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Mã hoặc tên thủ tục gốc đang thực hiện.</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">chu_de</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req optional\">tùy chọn</span>\n                  </div>\n                  <div class=\"param-desc\">Tên chủ đề / sự kiện đời sống (ví dụ: <code>sinh con</code>, <code>hộ kinh doanh</code>).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">limit</code>\n                    <span class=\"param-type\">number</span>\n                    <span class=\"param-req optional\">mặc định: 6</span>\n                  </div>\n                  <div class=\"param-desc\">Số lượng thủ tục cần gợi ý (1-20).</div>\n                </div>\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">dinh_dang</code>\n                    <span class=\"param-type\">enum</span>\n                    <span class=\"param-req optional\">mặc định: markdown</span>\n                  </div>\n                  <div class=\"param-desc\"><code>markdown</code> hoặc <code>json</code>.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"goi_y_thu_tuc_lien_quan\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 9: thong_tin_mcp_server -->\n          <div class=\"tool-doc-card\" data-tool=\"thong_tin_mcp_server\" data-category=\"he_thong\" style=\"--card-glow: rgba(99, 102, 241, 0.25); --accent-line: #6366f1;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #6366f1; background: rgba(99, 102, 241, 0.12); border-color: rgba(99, 102, 241, 0.28);\">\n                  <i class=\"bi bi-cpu-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">thong_tin_mcp_server</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"thong_tin_mcp_server\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Alias:</span>\n                    <span class=\"alias-code\">mcp_info</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge badge-info\"><i class=\"bi bi-dot\"></i> Hệ Thống</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Lấy thông tin chi tiết về phiên bản ứng dụng MCP, tác giả, chuẩn giao thức, thời điểm cập nhật và tình trạng kết nối cơ sở dữ liệu quốc gia hơn 6,700 thủ tục.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">0 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-desc\" style=\"color: var(--text-dim); font-style: italic;\">\n                  Không yêu cầu tham số đầu vào. Trả về cấu trúc JSON / Markdown về phiên bản và trạng thái runtime.\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"thong_tin_mcp_server\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-lightning-charge-fill\"></i> MCP & REST</span>\n            </div>\n          </div>\n\n          <!-- TOOL 10: search (Chuẩn OpenAI Agent) -->\n          <div class=\"tool-doc-card\" data-tool=\"search\" data-category=\"openai\" style=\"--card-glow: rgba(244, 63, 94, 0.25); --accent-line: #f43f5e;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #fb7185; background: rgba(244, 63, 94, 0.12); border-color: rgba(244, 63, 94, 0.28);\">\n                  <i class=\"bi bi-robot\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">search</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"search\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Chuẩn:</span>\n                    <span class=\"alias-code\">OpenAI Plugins</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge\" style=\"background: rgba(244, 63, 94, 0.18); color: #fb7185; border: 1px solid rgba(244, 63, 94, 0.35);\"><i class=\"bi bi-dot\"></i> OpenAI Agent</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Công cụ tìm kiếm thủ tục hành chính Việt Nam theo chuẩn OpenAI Agent Plugins & Deep Research Connector. Trả về cấu trúc JSON sạch <code>{\"results\":[{\"id\",\"title\",\"url\"}]}</code> để AI tiếp tục gọi <code>fetch</code>.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">1 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">query</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Từ khóa tìm kiếm thủ tục trong CSDL Quốc gia.</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tim_kiem_theo_ten_tthc\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-openai\"></i> OpenAI Standard</span>\n            </div>\n          </div>\n\n          <!-- TOOL 11: fetch (Chuẩn OpenAI Agent) -->\n          <div class=\"tool-doc-card\" data-tool=\"fetch\" data-category=\"openai\" style=\"--card-glow: rgba(244, 63, 94, 0.25); --accent-line: #f43f5e;\">\n            <div class=\"tool-card-accent\"></div>\n            <div class=\"tool-doc-header\">\n              <div class=\"tool-header-left\">\n                <div class=\"tool-icon-box\" style=\"color: #fb7185; background: rgba(244, 63, 94, 0.12); border-color: rgba(244, 63, 94, 0.28);\">\n                  <i class=\"bi bi-cloud-arrow-down-fill\"></i>\n                </div>\n                <div class=\"tool-title-col\">\n                  <div class=\"tool-name-row\">\n                    <span class=\"tool-name\">fetch</span>\n                    <button type=\"button\" class=\"btn-copy-tool-name\" data-copy=\"fetch\" title=\"Sao chép tên công cụ\">\n                      <i class=\"bi bi-clipboard\"></i>\n                    </button>\n                  </div>\n                  <div class=\"tool-alias-wrap\">\n                    <span><i class=\"bi bi-arrow-return-right\"></i> Chuẩn:</span>\n                    <span class=\"alias-code\">OpenAI Plugins</span>\n                  </div>\n                </div>\n              </div>\n              <span class=\"tool-header-badge\" style=\"background: rgba(244, 63, 94, 0.18); color: #fb7185; border: 1px solid rgba(244, 63, 94, 0.35);\"><i class=\"bi bi-dot\"></i> OpenAI Agent</span>\n            </div>\n            <p class=\"tool-doc-desc\">\n              Công cụ trích xuất toàn văn nội dung TTHC (hồ sơ, các bước giải quyết, căn cứ pháp lý, lệ phí) theo <code>id</code> hoặc mã TTHC theo chuẩn OpenAI Agent Plugins.\n            </p>\n            <div class=\"tool-params-section\">\n              <div class=\"params-header-row\">\n                <span class=\"params-heading\"><i class=\"bi bi-sliders2\"></i> Tham số Schema</span>\n                <span class=\"params-count-pill\">1 tham số</span>\n              </div>\n              <div class=\"params-list-items\">\n                <div class=\"param-item\">\n                  <div class=\"param-meta\">\n                    <code class=\"param-name\">id</code>\n                    <span class=\"param-type\">string</span>\n                    <span class=\"param-req required\">bắt buộc</span>\n                  </div>\n                  <div class=\"param-desc\">Mã định danh hoặc mã TTHC (ví dụ: <code>2.002189</code> hoặc <code>019d2bfd-...</code>).</div>\n                </div>\n              </div>\n            </div>\n            <div class=\"tool-doc-footer\">\n              <button type=\"button\" class=\"btn-try-tool\" data-tool=\"tra_cuu_theo_ma_tthc\">\n                <i class=\"bi bi-play-fill\"></i> Thử nghiệm ngay\n              </button>\n              <span class=\"tool-badge-protocol\"><i class=\"bi bi-openai\"></i> OpenAI Standard</span>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- Empty state when search has 0 results -->\n        <div class=\"docs-empty-state\" id=\"docs-empty-notice\" style=\"display: none;\">\n          <i class=\"bi bi-search\"></i>\n          <h3 style=\"font-size: 1.1rem; margin-bottom: 6px; color: #f1f5f9;\">Không tìm thấy công cụ phù hợp</h3>\n          <p style=\"font-size: 0.85rem; color: var(--text-dim); margin-bottom: 12px;\">Thử tìm kiếm với từ khóa khác hoặc bấm nút \"Tất cả\" bên trên để xem lại toàn bộ công cụ.</p>\n          <button type=\"button\" class=\"btn btn-secondary btn-xs\" id=\"btn-reset-tools-filter\">\n            <i class=\"bi bi-arrow-counterclockwise\"></i> Đặt lại bộ lọc\n          </button>\n        </div>\n\n        <div style=\"margin-top: 28px; text-align: center;\">\n          <a href=\"/openapi.json\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-sm\" style=\"display: inline-flex; align-items: center; gap: 8px;\">\n            <i class=\"bi bi-filetype-json\"></i> Xem Toàn Bộ OpenAPI Schema (/openapi.json)\n          </a>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <!-- Detail Modal -->\n  <div class=\"modal-overlay\" id=\"detail-modal\" style=\"display: none;\">\n    <div class=\"modal-card glass-card\">\n      <div class=\"modal-header\">\n        <div class=\"modal-header-left\">\n          <h3 class=\"modal-title\" id=\"modal-tthc-title\">Chi tiết thủ tục hành chính</h3>\n        </div>\n        <div class=\"modal-header-actions\" id=\"modal-header-actions\">\n          <div class=\"modal-view-mode-toggle\" id=\"modal-view-mode-toggle\" style=\"display: none;\">\n            <button class=\"btn btn-secondary btn-xs active\" id=\"btn-modal-mode-rendered\" title=\"Xem giao diện trình bày trực quan\">\n              <i class=\"bi bi-layout-text-window-reverse\"></i> Giao diện\n            </button>\n            <button class=\"btn btn-secondary btn-xs\" id=\"btn-modal-mode-markdown\" title=\"Xem văn bản Markdown có cấu trúc\">\n              <i class=\"bi bi-markdown-fill\"></i> Markdown\n            </button>\n          </div>\n          <button class=\"btn btn-secondary btn-xs\" id=\"btn-modal-copy-md\" title=\"Sao chép nội dung Markdown có cấu trúc\" style=\"display: none;\">\n            <i class=\"bi bi-clipboard\"></i> Sao chép MD\n          </button>\n          <button class=\"btn btn-primary btn-xs\" id=\"btn-modal-download-md\" title=\"Xuất và tải về tệp tin .md có cấu trúc đầy đủ\" style=\"display: none;\">\n            <i class=\"bi bi-download\"></i> Xuất .md\n          </button>\n          <button class=\"modal-close\" id=\"btn-close-modal\" title=\"Đóng cửa sổ\">\n            <i class=\"bi bi-x-lg\"></i>\n          </button>\n        </div>\n      </div>\n      <div class=\"modal-body\" id=\"modal-tthc-body\">\n        <div class=\"loader-container\">\n          <div class=\"spinner\"></div>\n          <p>Đang tải chi tiết hồ sơ...</p>\n        </div>\n      </div>\n      <div class=\"modal-body modal-markdown-viewport\" id=\"modal-tthc-markdown-viewport\" style=\"display: none;\">\n        <pre><code id=\"modal-tthc-markdown-code\"></code></pre>\n      </div>\n    </div>\n  </div>\n\n  <footer class=\"site-footer\">\n    <div class=\"container footer-container\">\n      <div class=\"footer-top-row\">\n        <div class=\"footer-brand\">\n          <span class=\"footer-brand-title\">\n            <img src=\"https://ik.imagekit.io/97moqce0c/Static/logo_uoCW9PIyz.png\" alt=\"MCP Logo\" class=\"footer-mini-logo\">\n            MCP TTHC Server\n          </span>\n        </div>\n        <div class=\"footer-badges\">\n          <span class=\"badge badge-warning\" id=\"footer-version-badge\">v1.1.0</span>\n          <span class=\"badge badge-primary\">Model Context Protocol</span>\n          <span class=\"badge badge-success\">Netlify Serverless</span>\n        </div>\n      </div>\n      <div class=\"footer-bottom-row\">\n        <p>© <span id=\"current-year\">2026</span> MCP Server TTHC DVCQG • Phát triển bởi Kyn Chou</p>\n      </div>\n    </div>\n  </footer>\n\n  <script src=\"app.js\"></script>\n</body>\n</html>\n";
export const EMBEDDED_STYLE_CSS: string = ":root {\n  --bg-main: #090d16;\n  --bg-card: rgba(17, 24, 39, 0.75);\n  --bg-card-hover: rgba(30, 41, 59, 0.85);\n  --border-color: rgba(255, 255, 255, 0.1);\n  --border-glow: rgba(56, 189, 248, 0.3);\n  \n  --primary: #38bdf8;\n  --primary-hover: #0ea5e9;\n  --primary-glow: rgba(56, 189, 248, 0.25);\n  \n  --accent-emerald: #10b981;\n  --accent-cyan: #06b6d4;\n  --accent-violet: #8b5cf6;\n  --accent-amber: #f59e0b;\n  --accent-rose: #f43f5e;\n  \n  --text-main: #f8fafc;\n  --text-muted: #94a3b8;\n  --text-dim: #64748b;\n  \n  --font-main: 'Outfit', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  --font-mono: 'JetBrains Mono', monospace;\n  \n  --radius-sm: 8px;\n  --radius-md: 14px;\n  --radius-lg: 20px;\n  --radius-full: 9999px;\n  \n  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background-color: var(--bg-main);\n  color: var(--text-main);\n  font-family: var(--font-main);\n  line-height: 1.6;\n  min-height: 100vh;\n  position: relative;\n  overflow-x: hidden;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Background Ambient Glows */\n.bg-glow {\n  position: fixed;\n  border-radius: 50%;\n  filter: blur(120px);\n  pointer-events: none;\n  z-index: 0;\n  opacity: 0.15;\n}\n.bg-glow-1 {\n  width: 500px;\n  height: 500px;\n  background: #38bdf8;\n  top: -100px;\n  left: -100px;\n}\n.bg-glow-2 {\n  width: 600px;\n  height: 600px;\n  background: #8b5cf6;\n  top: 40%;\n  right: -150px;\n}\n.bg-glow-3 {\n  width: 450px;\n  height: 450px;\n  background: #10b981;\n  bottom: -100px;\n  left: 20%;\n}\n\n.container {\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 0 24px;\n  width: 100%;\n  position: relative;\n  z-index: 1;\n}\n\n/* Glassmorphism Cards */\n.glass-card {\n  background: var(--bg-card);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  padding: 24px;\n  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.37);\n  transition: var(--transition);\n}\n.glass-card:hover {\n  border-color: rgba(255, 255, 255, 0.18);\n}\n\n/* Site Header */\n.site-header {\n  padding: 24px 0;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  backdrop-filter: blur(8px);\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  background: rgba(9, 13, 22, 0.85);\n}\n.header-container {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 16px;\n}\n.logo-area {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n.logo-badge {\n  width: 48px;\n  height: 48px;\n  border-radius: var(--radius-md);\n  background: rgba(15, 23, 42, 0.7);\n  border: 1px solid rgba(56, 189, 248, 0.35);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 0 20px rgba(56, 189, 248, 0.3);\n  overflow: hidden;\n  padding: 6px;\n}\n.logo-icon-img {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  display: block;\n}\n.logo-icon {\n  font-size: 24px;\n}\n.site-title-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n.site-title {\n  font-size: 1.5rem;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n  background: linear-gradient(120deg, #f8fafc, #38bdf8);\n  -webkit-background-clip: text;\n  background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n.author-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 12px;\n  border-radius: var(--radius-full);\n  background: linear-gradient(135deg, rgba(56, 189, 248, 0.15), rgba(139, 92, 246, 0.25));\n  border: 1px solid rgba(139, 92, 246, 0.45);\n  color: #c084fc;\n  font-size: 0.76rem;\n  font-weight: 700;\n  letter-spacing: 0.02em;\n  box-shadow: 0 0 16px rgba(139, 92, 246, 0.3);\n  transition: var(--transition);\n}\n.version-tag-badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 3px 9px;\n  border-radius: var(--radius-full);\n  background: rgba(16, 185, 129, 0.15);\n  border: 1px solid rgba(16, 185, 129, 0.4);\n  color: #34d399;\n  font-family: var(--font-mono);\n  font-size: 0.74rem;\n  font-weight: 700;\n  letter-spacing: 0.03em;\n}\n.author-badge:hover {\n  transform: translateY(-1px) scale(1.02);\n  border-color: #a855f7;\n  box-shadow: 0 0 24px rgba(168, 85, 247, 0.45);\n}\n.site-subtitle {\n  font-size: 0.85rem;\n  color: var(--text-muted);\n  margin-top: 2px;\n}\n\n.header-status {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n\n.record-count-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 14px;\n  border-radius: var(--radius-full);\n  background: rgba(56, 189, 248, 0.1);\n  border: 1px solid rgba(56, 189, 248, 0.2);\n  color: var(--primary);\n  font-size: 0.85rem;\n  font-weight: 600;\n}\n\n.header-updated-badge {\n  background: rgba(245, 158, 11, 0.1);\n  border-color: rgba(245, 158, 11, 0.28);\n  color: #fbbf24;\n}\n.header-updated-badge i {\n  color: #f59e0b;\n}\n.header-updated-badge strong {\n  font-weight: 600;\n  color: #fef3c7;\n}\n.status-indicator {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 14px;\n  border-radius: var(--radius-full);\n  background: rgba(16, 185, 129, 0.1);\n  border: 1px solid rgba(16, 185, 129, 0.25);\n  font-size: 0.85rem;\n  color: var(--accent-emerald);\n  font-weight: 500;\n}\n.pulse-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background-color: var(--accent-emerald);\n  box-shadow: 0 0 10px var(--accent-emerald);\n  animation: pulse 2s infinite;\n}\n@keyframes pulse {\n  0% { transform: scale(0.95); opacity: 0.8; }\n  50% { transform: scale(1.3); opacity: 1; }\n  100% { transform: scale(0.95); opacity: 0.8; }\n}\n\n.latency-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  background: rgba(56, 189, 248, 0.15);\n  border: 1px solid rgba(56, 189, 248, 0.35);\n  color: #38bdf8;\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  font-weight: 700;\n  padding: 1px 7px;\n  border-radius: var(--radius-full);\n  margin-left: 4px;\n  letter-spacing: 0.02em;\n  transition: var(--transition);\n}\n.latency-pill i {\n  font-size: 0.7rem;\n}\n.latency-pill.fast {\n  background: rgba(16, 185, 129, 0.18);\n  border-color: rgba(52, 211, 153, 0.45);\n  color: #34d399;\n}\n.latency-pill.medium {\n  background: rgba(245, 158, 11, 0.18);\n  border-color: rgba(251, 191, 36, 0.45);\n  color: #fbbf24;\n}\n.badge-cyan {\n  background: rgba(6, 182, 212, 0.15);\n  color: #22d3ee;\n  border: 1px solid rgba(6, 182, 212, 0.35);\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  font-weight: 600;\n}\n\n\n/* Config Bar */\n.config-bar {\n  margin: 24px 0 20px 0;\n}\n.config-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 20px;\n}\n@media (max-width: 768px) {\n  .config-grid { grid-template-columns: 1fr; }\n}\n\n.config-item {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.config-item label {\n  font-size: 0.875rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.input-with-action {\n  display: flex;\n  gap: 8px;\n}\n.input-with-action input {\n  flex: 1;\n  background: rgba(15, 23, 42, 0.7);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: var(--radius-sm);\n  padding: 9px 14px;\n  color: var(--text-main);\n  font-family: var(--font-mono);\n  font-size: 0.85rem;\n  outline: none;\n  transition: var(--transition);\n}\n.input-with-action input:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 2px var(--primary-glow);\n}\n.auth-notice {\n  margin-top: 14px;\n  padding-top: 12px;\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n  font-size: 0.8rem;\n  color: var(--text-muted);\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.auth-notice code {\n  color: var(--primary);\n  background: rgba(56, 189, 248, 0.12);\n  padding: 2px 6px;\n  border-radius: 4px;\n  font-family: var(--font-mono);\n}\n\n/* Navigation Tabs */\n.nav-tabs-wrapper {\n  margin-bottom: 24px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n}\n.nav-tabs {\n  display: flex;\n  gap: 8px;\n  overflow-x: auto;\n  padding-bottom: 8px;\n}\n.tab-btn {\n  background: transparent;\n  border: none;\n  padding: 10px 18px;\n  border-radius: var(--radius-sm);\n  color: var(--text-muted);\n  font-family: var(--font-main);\n  font-size: 0.95rem;\n  font-weight: 500;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  transition: var(--transition);\n  white-space: nowrap;\n}\n.tab-btn:hover {\n  color: var(--text-main);\n  background: rgba(255, 255, 255, 0.05);\n}\n.tab-btn.active {\n  color: var(--primary);\n  background: rgba(56, 189, 248, 0.12);\n  font-weight: 600;\n  border-bottom: 2px solid var(--primary);\n}\n\n/* Tab Panels */\n.tab-panel {\n  display: none;\n}\n.tab-panel.active {\n  display: block;\n}\n\n/* Playground Layout */\n.playground-layout {\n  display: grid;\n  grid-template-columns: 460px 1fr;\n  gap: 24px;\n  align-items: start;\n}\n@media (max-width: 1024px) {\n  .playground-layout { grid-template-columns: 1fr; }\n}\n\n.section-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n  margin-bottom: 16px;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--text-main);\n}\n.section-desc {\n  font-size: 0.9rem;\n  color: var(--text-muted);\n  margin-bottom: 20px;\n}\n\n/* Forms & Inputs */\n.tool-selector-group {\n  margin-bottom: 18px;\n}\n.input-label {\n  display: block;\n  font-size: 0.85rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  margin-bottom: 6px;\n}\n.form-select, .form-input {\n  width: 100%;\n  background: rgba(15, 23, 42, 0.85);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: var(--radius-sm);\n  padding: 10px 14px;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.9rem;\n  outline: none;\n  transition: var(--transition);\n}\n.form-select:focus, .form-input:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 2px var(--primary-glow);\n}\n.form-input-sm, .form-select-sm {\n  background: rgba(15, 23, 42, 0.85);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: var(--radius-sm);\n  padding: 6px 10px;\n  color: var(--text-main);\n  font-family: var(--font-main);\n  font-size: 0.85rem;\n  outline: none;\n}\n.helper-text {\n  display: block;\n  font-size: 0.75rem;\n  color: var(--text-dim);\n  margin-top: 4px;\n}\n\n.quick-chips {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n  margin-top: 10px;\n}\n.chip-label {\n  font-size: 0.75rem;\n  color: var(--text-dim);\n}\n.btn-chip {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  color: var(--text-muted);\n  font-size: 0.75rem;\n  padding: 3px 8px;\n  border-radius: var(--radius-full);\n  cursor: pointer;\n  transition: var(--transition);\n}\n.btn-chip:hover {\n  background: rgba(56, 189, 248, 0.15);\n  color: var(--primary);\n  border-color: var(--primary);\n}\n\n.pagination-row {\n  display: flex;\n  gap: 16px;\n  margin: 18px 0;\n  padding: 12px;\n  background: rgba(15, 23, 42, 0.4);\n  border-radius: var(--radius-sm);\n}\n.pagination-field {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 0.85rem;\n  color: var(--text-muted);\n}\n.pagination-field input {\n  width: 65px;\n}\n\n.form-row {\n  display: flex;\n  gap: 12px;\n}\n.form-col {\n  flex: 1;\n}\n.mt-2 { margin-top: 10px; }\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 10px 18px;\n  border-radius: var(--radius-sm);\n  font-family: var(--font-main);\n  font-size: 0.9rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: var(--transition);\n  border: 1px solid transparent;\n}\n.btn-primary {\n  background: linear-gradient(135deg, #0284c7, #2563eb);\n  color: #fff;\n  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.35);\n}\n.btn-primary:hover {\n  background: linear-gradient(135deg, #0369a1, #1d4ed8);\n  transform: translateY(-1px);\n  box-shadow: 0 6px 20px rgba(37, 99, 235, 0.45);\n}\n.btn-secondary {\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--text-main);\n  border-color: rgba(255, 255, 255, 0.15);\n}\n.btn-secondary:hover {\n  background: rgba(255, 255, 255, 0.14);\n}\n.btn-block { width: 100%; }\n.btn-sm { padding: 6px 12px; font-size: 0.8rem; }\n.btn-xs { padding: 4px 8px; font-size: 0.75rem; }\n.btn-icon { background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1); }\n\n.btn-spinner {\n  width: 16px;\n  height: 16px;\n  border: 2px solid rgba(255, 255, 255, 0.3);\n  border-top-color: #fff;\n  border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n}\n@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n\n/* Result Display */\n.result-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 12px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n  padding-bottom: 14px;\n  margin-bottom: 16px;\n}\n.result-title-group {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n.result-title-group .section-title {\n  margin-bottom: 0;\n}\n.execution-time-badge {\n  background: rgba(16, 185, 129, 0.15);\n  color: var(--accent-emerald);\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 2px 8px;\n  border-radius: var(--radius-full);\n}\n\n.view-toggle-group {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.toggle-btn {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  color: var(--text-muted);\n  font-size: 0.75rem;\n  padding: 4px 10px;\n  border-radius: var(--radius-sm);\n  cursor: pointer;\n  transition: var(--transition);\n}\n.toggle-btn.active {\n  background: var(--primary);\n  color: #090d16;\n  font-weight: 600;\n  border-color: var(--primary);\n}\n\n.result-viewport-container {\n  min-height: 480px;\n  max-height: 750px;\n  overflow-y: auto;\n  padding-right: 4px;\n}\n.viewport-code {\n  background: rgba(10, 15, 29, 0.8);\n  border-radius: var(--radius-sm);\n  padding: 16px;\n  color: #38bdf8;\n  font-family: var(--font-mono);\n  font-size: 0.82rem;\n  line-height: 1.5;\n  white-space: pre-wrap;\n  word-break: break-word;\n}\n\n/* Empty State */\n.empty-state {\n  text-align: center;\n  padding: 80px 20px;\n  color: var(--text-muted);\n}\n.empty-icon {\n  font-size: 48px;\n  margin-bottom: 16px;\n  opacity: 0.6;\n}\n.empty-state h3 {\n  font-size: 1.2rem;\n  color: var(--text-main);\n  margin-bottom: 8px;\n}\n\n/* Rendered Cards & Tables */\n.rendered-item-card {\n  background: rgba(15, 23, 42, 0.65);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-sm);\n  padding: 16px;\n  margin-bottom: 14px;\n  transition: var(--transition);\n}\n.rendered-item-card:hover {\n  border-color: rgba(56, 189, 248, 0.4);\n  background: rgba(15, 23, 42, 0.9);\n}\n.rendered-item-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 8px;\n}\n.rendered-item-title {\n  font-size: 1rem;\n  font-weight: 600;\n  color: var(--text-main);\n  line-height: 1.4;\n}\n.badge {\n  display: inline-block;\n  padding: 3px 8px;\n  font-size: 0.72rem;\n  font-weight: 600;\n  border-radius: var(--radius-full);\n  white-space: nowrap;\n}\n.badge-primary { background: rgba(56, 189, 248, 0.15); color: #38bdf8; }\n.badge-success { background: rgba(16, 185, 129, 0.15); color: #10b981; }\n.badge-warning { background: rgba(245, 158, 11, 0.15); color: #f59e0b; }\n.badge-purple { background: rgba(139, 92, 246, 0.15); color: #a78bfa; }\n.badge-secondary { background: rgba(255, 255, 255, 0.1); color: var(--text-muted); }\n.badge-danger { background: rgba(244, 63, 94, 0.15); color: #f43f5e; }\n\n.rendered-item-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 14px;\n  font-size: 0.8rem;\n  color: var(--text-muted);\n  margin-bottom: 10px;\n}\n.rendered-item-meta span strong {\n  color: var(--text-main);\n}\n.rendered-item-actions {\n  display: flex;\n  justify-content: flex-end;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n/* Detail View (Rendered inside Viewport or Modal) */\n.detail-view {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n.detail-header-block {\n  border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n  padding-bottom: 14px;\n}\n.detail-code-badge {\n  display: inline-block;\n  font-family: var(--font-mono);\n  background: rgba(56, 189, 248, 0.15);\n  color: var(--primary);\n  padding: 4px 10px;\n  border-radius: var(--radius-sm);\n  font-size: 0.85rem;\n  margin-bottom: 8px;\n}\n.detail-title {\n  font-size: 1.25rem;\n  font-weight: 700;\n  margin-bottom: 8px;\n  line-height: 1.45;\n  color: #fff;\n}\n\n/* Modern Hero Summary Card */\n.meta-summary-card {\n  background: linear-gradient(145deg, rgba(15, 23, 42, 0.85) 0%, rgba(30, 41, 59, 0.55) 100%);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-radius: var(--radius-md);\n  padding: 16px 18px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);\n}\n\n.meta-badges-bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n  margin-bottom: 14px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.07);\n}\n\n.meta-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.78rem;\n  font-weight: 600;\n  padding: 4px 10px;\n  border-radius: 9999px;\n  letter-spacing: 0.01em;\n}\n.meta-pill i {\n  font-size: 0.85rem;\n}\n.meta-pill-code {\n  background: rgba(56, 189, 248, 0.15);\n  color: #38bdf8;\n  border: 1px solid rgba(56, 189, 248, 0.35);\n  font-family: var(--font-mono);\n}\n.meta-pill-qdcb {\n  background: rgba(245, 158, 11, 0.14);\n  color: #fbbf24;\n  border: 1px solid rgba(245, 158, 11, 0.38);\n  text-decoration: none;\n  transition: var(--transition);\n}\na.meta-pill-qdcb:hover {\n  background: rgba(245, 158, 11, 0.25);\n  border-color: rgba(245, 158, 11, 0.6);\n  color: #fde68a;\n  transform: translateY(-1px);\n}\n.meta-pill-cap {\n  background: rgba(168, 85, 247, 0.15);\n  color: #c084fc;\n  border: 1px solid rgba(168, 85, 247, 0.35);\n}\n.meta-pill-field {\n  background: rgba(59, 130, 246, 0.15);\n  color: #60a5fa;\n  border: 1px solid rgba(59, 130, 246, 0.35);\n}\n.meta-pill-fee {\n  background: rgba(245, 158, 11, 0.15);\n  color: #fbbf24;\n  border: 1px solid rgba(245, 158, 11, 0.35);\n}\n.meta-pill-type {\n  background: rgba(148, 163, 184, 0.12);\n  color: #cbd5e1;\n  border: 1px solid rgba(148, 163, 184, 0.25);\n}\n.meta-pill-dvctt-toan-trinh {\n  background: rgba(16, 185, 129, 0.15);\n  color: #34d399;\n  border: 1px solid rgba(16, 185, 129, 0.4);\n}\n.meta-pill-dvctt-mot-phan {\n  background: rgba(245, 158, 11, 0.15);\n  color: #fbbf24;\n  border: 1px solid rgba(245, 158, 11, 0.4);\n}\n.meta-pill-dvctt-chua {\n  background: rgba(148, 163, 184, 0.15);\n  color: #94a3b8;\n  border: 1px solid rgba(148, 163, 184, 0.3);\n}\n\n.meta-summary-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));\n  gap: 10px;\n  margin-bottom: 10px;\n}\n\n.meta-grid-item {\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n  padding: 10px 12px;\n  background: rgba(0, 0, 0, 0.25);\n  border: 1px solid rgba(255, 255, 255, 0.05);\n  border-radius: var(--radius-sm);\n  transition: var(--transition);\n}\n.meta-grid-item:hover {\n  background: rgba(0, 0, 0, 0.35);\n  border-color: rgba(255, 255, 255, 0.1);\n}\n.meta-item-icon {\n  font-size: 1.1rem;\n  color: var(--primary);\n  margin-top: 1px;\n  flex-shrink: 0;\n}\n.meta-item-content {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  overflow: hidden;\n}\n.meta-item-label {\n  font-size: 0.72rem;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--text-dim);\n  font-weight: 600;\n}\n.meta-item-val {\n  font-size: 0.84rem;\n  color: var(--text-main);\n  font-weight: 500;\n  line-height: 1.4;\n  word-break: break-word;\n}\n\n/* Collapsible Details in Hero Card */\n.meta-collapse-details {\n  background: rgba(0, 0, 0, 0.22);\n  border: 1px dashed rgba(255, 255, 255, 0.1);\n  border-radius: var(--radius-sm);\n  overflow: hidden;\n  margin-top: 8px;\n}\n.meta-collapse-summary {\n  padding: 8px 12px;\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: #94a3b8;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  user-select: none;\n  transition: var(--transition);\n}\n.meta-collapse-summary:hover {\n  color: var(--primary);\n  background: rgba(255, 255, 255, 0.03);\n}\n.meta-collapse-summary .collapse-icon {\n  transition: transform 0.2s ease;\n  font-size: 0.75rem;\n  margin-left: auto;\n}\n.meta-collapse-details[open] .meta-collapse-summary .collapse-icon {\n  transform: rotate(180deg);\n}\n.meta-collapse-content {\n  padding: 12px;\n  border-top: 1px solid rgba(255, 255, 255, 0.06);\n  font-size: 0.82rem;\n  color: var(--text-muted);\n}\n.meta-dates-wrap {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));\n  gap: 8px;\n  margin-top: 8px;\n}\n.meta-date-col {\n  background: rgba(255, 255, 255, 0.03);\n  padding: 6px 10px;\n  border-radius: 6px;\n  border: 1px solid rgba(255, 255, 255, 0.05);\n}\n.meta-date-label {\n  font-size: 0.7rem;\n  color: var(--text-dim);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n.meta-date-val {\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--text-main);\n  margin-top: 2px;\n}\n\n/* Quick Navigation Chips */\n.detail-quick-nav {\n  display: flex;\n  gap: 6px;\n  overflow-x: auto;\n  padding: 4px 0 10px 0;\n  margin: 6px 0 4px 0;\n  scrollbar-width: thin;\n}\n.detail-quick-nav::-webkit-scrollbar {\n  height: 4px;\n}\n.detail-quick-nav::-webkit-scrollbar-thumb {\n  background: rgba(255, 255, 255, 0.15);\n  border-radius: 4px;\n}\n.quick-nav-chip {\n  flex-shrink: 0;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.76rem;\n  font-weight: 500;\n  color: #94a3b8;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  padding: 5px 11px;\n  border-radius: 9999px;\n  text-decoration: none;\n  cursor: pointer;\n  transition: var(--transition);\n}\n.quick-nav-chip:hover {\n  background: rgba(56, 189, 248, 0.15);\n  color: #38bdf8;\n  border-color: rgba(56, 189, 248, 0.35);\n  transform: translateY(-1px);\n}\n.quick-nav-chip.active {\n  background: var(--primary);\n  color: #0b1120;\n  font-weight: 600;\n  border-color: var(--primary);\n}\n\n/* Card sections inside detail view */\n.section-card {\n  background: rgba(15, 23, 42, 0.65);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-md);\n  padding: 16px 20px;\n  transition: var(--transition);\n  scroll-margin-top: 14px;\n}\n.section-card:hover {\n  border-color: rgba(255, 255, 255, 0.15);\n  background: rgba(15, 23, 42, 0.85);\n}\n.section-card-method {\n  border-left: 4px solid var(--accent-cyan);\n}\n.section-card-time {\n  border-left: 4px solid var(--accent-amber);\n}\n.section-card-steps {\n  border-left: 4px solid var(--primary);\n}\n.section-card-docs {\n  border-left: 4px solid var(--accent-emerald);\n}\n.section-card-fee {\n  border-left: 4px solid var(--accent-violet);\n}\n.section-card-basis {\n  border-left: 4px solid var(--accent-rose);\n}\n\n.section-card-header-toggle {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  cursor: pointer;\n  user-select: none;\n  width: 100%;\n}\n.section-card.collapsible.collapsed .section-card-content {\n  display: none;\n}\n.section-card .toggle-chevron {\n  color: var(--text-dim);\n  font-size: 0.85rem;\n  transition: transform 0.2s ease;\n}\n.section-card.collapsible.collapsed .toggle-chevron {\n  transform: rotate(-90deg);\n}\n.section-card-count-badge {\n  font-size: 0.72rem;\n  padding: 2px 8px;\n  border-radius: 9999px;\n  background: rgba(255, 255, 255, 0.08);\n  color: #cbd5e1;\n  font-weight: 500;\n  margin-left: 6px;\n}\n\n.detail-section-title {\n  font-size: 1.05rem;\n  font-weight: 700;\n  color: var(--text-main);\n  margin-bottom: 12px;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.detail-group-label {\n  font-size: 0.88rem;\n  font-weight: 700;\n  color: var(--primary);\n  margin: 10px 0 6px 0;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n}\n.detail-subsection-title {\n  font-size: 0.92rem;\n  font-weight: 600;\n  color: #38bdf8;\n  margin: 12px 0 6px 0;\n}\n.detail-list-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  font-size: 0.86rem;\n  margin-bottom: 6px;\n  color: var(--text-muted);\n  line-height: 1.5;\n}\n.detail-list-item strong {\n  color: var(--text-main);\n}\n.detail-list-item code {\n  color: #38bdf8;\n  background: rgba(56, 189, 248, 0.12);\n  padding: 1px 6px;\n  border-radius: 4px;\n  font-family: var(--font-mono);\n  font-size: 0.82rem;\n}\n.list-bullet {\n  color: var(--primary);\n  font-size: 1rem;\n  line-height: 1.2;\n}\n.list-text {\n  flex: 1;\n}\n.detail-note {\n  font-size: 0.82rem;\n  color: var(--text-dim);\n  margin: 4px 0 8px 16px;\n}\n.detail-paragraph {\n  font-size: 0.88rem;\n  color: var(--text-muted);\n  margin-bottom: 8px;\n  line-height: 1.5;\n}\n\n.step-item {\n  background: rgba(15, 23, 42, 0.5);\n  border-left: 3px solid var(--primary);\n  padding: 10px 14px;\n  margin-bottom: 10px;\n  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;\n}\n.step-name {\n  font-weight: 600;\n  color: var(--text-main);\n  font-size: 0.9rem;\n  margin-bottom: 4px;\n}\n.step-desc {\n  font-size: 0.83rem;\n  color: var(--text-muted);\n  line-height: 1.5;\n}\n\n/* Tab 2: Code Config Box */\n.client-tabs {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 14px;\n  overflow-x: auto;\n}\n.client-tab {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  color: var(--text-muted);\n  padding: 8px 16px;\n  border-radius: var(--radius-sm);\n  font-size: 0.85rem;\n  cursor: pointer;\n  transition: var(--transition);\n}\n.client-tab.active {\n  background: rgba(56, 189, 248, 0.15);\n  color: var(--primary);\n  border-color: var(--primary);\n  font-weight: 600;\n}\n.code-box-wrapper {\n  background: #060913;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-radius: var(--radius-sm);\n  overflow: hidden;\n}\n.code-box-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px 14px;\n  background: rgba(255, 255, 255, 0.03);\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n}\n.file-label {\n  font-size: 0.75rem;\n  font-family: var(--font-mono);\n  color: var(--text-dim);\n}\n.code-box {\n  padding: 16px;\n  color: #38bdf8;\n  font-family: var(--font-mono);\n  font-size: 0.85rem;\n  line-height: 1.5;\n  overflow-x: auto;\n}\n\n/* Tab 3: Modern Tools Grid & Cardbox Styling */\n.docs-toolbar {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin-bottom: 24px;\n  background: rgba(15, 23, 42, 0.65);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-md);\n  padding: 16px 18px;\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n  box-shadow: 0 4px 20px -2px rgba(0, 0, 0, 0.25);\n}\n\n.docs-search-row {\n  display: flex;\n  gap: 12px;\n  align-items: center;\n}\n\n.docs-search-box {\n  position: relative;\n  flex: 1;\n}\n\n.docs-search-box .search-icon {\n  position: absolute;\n  left: 14px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--text-dim);\n  font-size: 0.95rem;\n  pointer-events: none;\n}\n\n.docs-search-box input {\n  padding-left: 38px;\n  padding-right: 36px;\n  height: 42px;\n  background: rgba(10, 15, 28, 0.75);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-radius: 10px;\n  font-size: 0.9rem;\n  color: var(--text-main);\n  transition: var(--transition);\n  width: 100%;\n}\n\n.docs-search-box input:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);\n  background: rgba(15, 23, 42, 0.9);\n  outline: none;\n}\n\n.btn-clear-tool-search {\n  position: absolute;\n  right: 12px;\n  top: 50%;\n  transform: translateY(-50%);\n  background: none;\n  border: none;\n  color: var(--text-dim);\n  cursor: pointer;\n  padding: 4px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: color 0.2s;\n}\n\n.btn-clear-tool-search:hover {\n  color: var(--text-main);\n}\n\n.docs-filter-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n}\n\n.filter-chip-label {\n  font-size: 0.8rem;\n  color: var(--text-dim);\n  font-weight: 500;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-right: 4px;\n}\n\n.filter-chip {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  color: var(--text-muted);\n  padding: 6px 14px;\n  border-radius: 20px;\n  font-size: 0.78rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: var(--transition);\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.filter-chip:hover {\n  background: rgba(255, 255, 255, 0.1);\n  color: var(--text-main);\n  border-color: rgba(255, 255, 255, 0.2);\n}\n\n.filter-chip.active {\n  background: rgba(56, 189, 248, 0.15);\n  border-color: rgba(56, 189, 248, 0.4);\n  color: var(--primary);\n  box-shadow: 0 0 12px rgba(56, 189, 248, 0.2);\n}\n\n.tools-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(370px, 1fr));\n  gap: 22px;\n}\n\n.tool-doc-card {\n  position: relative;\n  background: linear-gradient(155deg, rgba(23, 32, 54, 0.75) 0%, rgba(13, 19, 35, 0.9) 100%);\n  border: 1px solid rgba(255, 255, 255, 0.09);\n  border-radius: 16px;\n  padding: 22px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  backdrop-filter: blur(14px);\n  -webkit-backdrop-filter: blur(14px);\n  box-shadow: 0 4px 20px -2px rgba(0, 0, 0, 0.35);\n  transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.28s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.28s ease;\n  overflow: hidden;\n}\n\n.tool-doc-card:hover {\n  transform: translateY(-4px);\n  border-color: rgba(56, 189, 248, 0.35);\n  box-shadow: 0 16px 36px -10px rgba(0, 0, 0, 0.55), 0 0 24px -6px var(--card-glow, rgba(56, 189, 248, 0.25));\n}\n\n.tool-card-accent {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 3px;\n  background: linear-gradient(90deg, transparent, var(--accent-line, #38bdf8), transparent);\n  opacity: 0.75;\n  transition: opacity 0.3s;\n}\n\n.tool-doc-card:hover .tool-card-accent {\n  opacity: 1;\n  height: 3.5px;\n}\n\n.tool-doc-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 14px;\n}\n\n.tool-header-left {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  min-width: 0;\n}\n\n.tool-icon-box {\n  width: 42px;\n  height: 42px;\n  border-radius: 12px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 1.25rem;\n  flex-shrink: 0;\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  transition: transform 0.25s, box-shadow 0.25s;\n}\n\n.tool-doc-card:hover .tool-icon-box {\n  transform: scale(1.05);\n}\n\n.tool-title-col {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n}\n\n.tool-name-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.tool-name {\n  font-family: var(--font-mono);\n  font-size: 0.96rem;\n  font-weight: 700;\n  color: #f1f5f9;\n  letter-spacing: -0.01em;\n  word-break: break-all;\n}\n\n.btn-copy-tool-name {\n  background: transparent;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 6px;\n  color: var(--text-dim);\n  width: 26px;\n  height: 26px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition: var(--transition);\n  font-size: 0.8rem;\n  flex-shrink: 0;\n}\n\n.btn-copy-tool-name:hover {\n  background: rgba(255, 255, 255, 0.1);\n  color: var(--primary);\n  border-color: rgba(56, 189, 248, 0.3);\n}\n\n.btn-copy-tool-name.copied {\n  background: rgba(16, 185, 129, 0.2);\n  color: #34d399;\n  border-color: rgba(16, 185, 129, 0.4);\n}\n\n.tool-alias-wrap {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 0.75rem;\n  color: var(--text-dim);\n}\n\n.tool-alias-wrap .alias-code {\n  font-family: var(--font-mono);\n  background: rgba(255, 255, 255, 0.06);\n  padding: 1px 6px;\n  border-radius: 4px;\n  color: #94a3b8;\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  font-size: 0.72rem;\n}\n\n.tool-header-badge {\n  flex-shrink: 0;\n  font-size: 0.72rem;\n  padding: 4px 9px;\n  border-radius: 20px;\n  font-weight: 600;\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  letter-spacing: 0.01em;\n}\n\n.tool-doc-desc {\n  font-size: 0.85rem;\n  line-height: 1.55;\n  color: #cbd5e1;\n  margin-bottom: 16px;\n  flex-grow: 1;\n}\n\n.tool-params-section {\n  background: rgba(10, 15, 29, 0.65);\n  border: 1px solid rgba(255, 255, 255, 0.06);\n  border-radius: 10px;\n  padding: 12px 14px;\n  margin-bottom: 16px;\n}\n\n.params-header-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 10px;\n  padding-bottom: 6px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n}\n\n.params-heading {\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: #94a3b8;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.params-count-pill {\n  font-size: 0.7rem;\n  background: rgba(255, 255, 255, 0.07);\n  color: #94a3b8;\n  padding: 2px 7px;\n  border-radius: 10px;\n  font-weight: 500;\n  font-family: var(--font-mono);\n}\n\n.params-list-items {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.param-item {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  font-size: 0.78rem;\n}\n\n.param-meta {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.param-name {\n  font-family: var(--font-mono);\n  color: #38bdf8;\n  font-weight: 600;\n  background: rgba(56, 189, 248, 0.1);\n  padding: 1px 6px;\n  border-radius: 4px;\n  border: 1px solid rgba(56, 189, 248, 0.2);\n}\n\n.param-type {\n  font-family: var(--font-mono);\n  font-size: 0.7rem;\n  color: #c084fc;\n  background: rgba(168, 85, 247, 0.1);\n  padding: 1px 5px;\n  border-radius: 4px;\n}\n\n.param-req {\n  font-size: 0.68rem;\n  padding: 1px 5px;\n  border-radius: 4px;\n  font-weight: 500;\n}\n\n.param-req.required {\n  background: rgba(244, 63, 94, 0.15);\n  color: #fb7185;\n  border: 1px solid rgba(244, 63, 94, 0.25);\n}\n\n.param-req.optional {\n  background: rgba(148, 163, 184, 0.1);\n  color: #94a3b8;\n}\n\n.param-desc {\n  color: #94a3b8;\n  font-size: 0.76rem;\n  line-height: 1.45;\n  padding-left: 2px;\n}\n\n.param-desc code {\n  color: #38bdf8;\n  font-family: var(--font-mono);\n  background: rgba(255, 255, 255, 0.05);\n  padding: 0 4px;\n  border-radius: 3px;\n}\n\n.tool-doc-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-top: 14px;\n  border-top: 1px solid rgba(255, 255, 255, 0.07);\n}\n\n.btn-try-tool {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.8rem;\n  font-weight: 600;\n  padding: 6px 14px;\n  border-radius: 8px;\n  cursor: pointer;\n  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);\n  color: #ffffff;\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  box-shadow: 0 2px 8px rgba(2, 132, 199, 0.35);\n  transition: var(--transition);\n}\n\n.btn-try-tool:hover {\n  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%);\n  box-shadow: 0 4px 14px rgba(14, 165, 233, 0.45);\n  transform: translateY(-1px);\n}\n\n.tool-badge-protocol {\n  font-size: 0.72rem;\n  color: var(--text-dim);\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n}\n\n.tool-badge-protocol i {\n  color: #38bdf8;\n}\n\n.docs-empty-state {\n  text-align: center;\n  padding: 48px 20px;\n  background: rgba(15, 23, 42, 0.4);\n  border: 1px dashed rgba(255, 255, 255, 0.1);\n  border-radius: 16px;\n  color: var(--text-muted);\n}\n\n.docs-empty-state i {\n  font-size: 2.5rem;\n  color: var(--text-dim);\n  margin-bottom: 12px;\n  display: block;\n}\n\n/* Tab 4: Deploy Steps */\n.deploy-steps {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n.step-card {\n  display: flex;\n  gap: 18px;\n  background: rgba(15, 23, 42, 0.6);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-sm);\n  padding: 20px;\n}\n.step-num {\n  width: 38px;\n  height: 38px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, #0284c7, #6366f1);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  font-size: 1.1rem;\n  flex-shrink: 0;\n}\n.step-content {\n  flex: 1;\n}\n.step-content h3 {\n  font-size: 1.1rem;\n  margin-bottom: 8px;\n}\n.step-content p, .step-content ul {\n  font-size: 0.88rem;\n  color: var(--text-muted);\n  margin-bottom: 8px;\n}\n.step-content ul {\n  padding-left: 20px;\n}\n.step-code {\n  background: #060913;\n  padding: 12px;\n  border-radius: var(--radius-sm);\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  color: #38bdf8;\n  margin-top: 10px;\n  overflow-x: auto;\n}\n.env-table {\n  width: 100%;\n  border-collapse: collapse;\n  margin-top: 10px;\n  font-size: 0.85rem;\n}\n.env-table th, .env-table td {\n  padding: 8px 12px;\n  text-align: left;\n  border: 1px solid rgba(255, 255, 255, 0.1);\n}\n.env-table th {\n  background: rgba(255, 255, 255, 0.05);\n}\n\n/* Modal */\n.modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.75);\n  backdrop-filter: blur(8px);\n  z-index: 100;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n.modal-card {\n  width: 100%;\n  max-width: min(980px, 94vw);\n  max-height: 88vh;\n  display: flex;\n  flex-direction: column;\n  padding: 0;\n  overflow: hidden;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.1);\n  border-radius: var(--radius-lg, 16px);\n}\n.modal-header {\n  padding: 16px 22px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n  background: rgba(15, 23, 42, 0.95);\n  backdrop-filter: blur(10px);\n}\n.modal-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n}\n.modal-close {\n  background: transparent;\n  border: none;\n  color: var(--text-muted);\n  font-size: 1.25rem;\n  cursor: pointer;\n  padding: 4px;\n}\n.modal-close:hover { color: #fff; }\n.modal-body {\n  padding: 24px;\n  overflow-y: auto;\n}\n.loader-container {\n  text-align: center;\n  padding: 40px;\n  color: var(--text-muted);\n}\n.spinner {\n  width: 36px;\n  height: 36px;\n  border: 3px solid rgba(255, 255, 255, 0.2);\n  border-top-color: var(--primary);\n  border-radius: 50%;\n  margin: 0 auto 16px auto;\n  animation: spin 0.8s linear infinite;\n}\n\n/* Toast Notification */\n.toast-notification {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  background: rgba(16, 185, 129, 0.95);\n  color: #fff;\n  padding: 10px 20px;\n  border-radius: var(--radius-sm);\n  font-size: 0.85rem;\n  font-weight: 600;\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);\n  transform: translateY(30px);\n  opacity: 0;\n  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n  z-index: 1000;\n}\n.toast-notification.show {\n  transform: translateY(0);\n  opacity: 1;\n}\n\n/* Footer */\n.site-footer {\n  margin-top: auto;\n  padding: 36px 0 28px 0;\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n  background: rgba(6, 9, 17, 0.7);\n  backdrop-filter: blur(12px);\n}\n.footer-container {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n.footer-top-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 14px;\n}\n.footer-brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n.footer-brand-title {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  font-weight: 700;\n  font-size: 1rem;\n  color: var(--text-main);\n  letter-spacing: -0.01em;\n}\n.footer-mini-logo {\n  width: 22px;\n  height: 22px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n.author-pill {\n  color: #c084fc;\n  font-size: 0.8rem;\n  background: rgba(139, 92, 246, 0.12);\n  padding: 4px 12px;\n  border-radius: var(--radius-full);\n  border: 1px solid rgba(139, 92, 246, 0.3);\n}\n.footer-badges {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.footer-bottom-row {\n  padding-top: 12px;\n  border-top: 1px solid rgba(255, 255, 255, 0.05);\n  font-size: 0.78rem;\n  color: var(--text-dim);\n  text-align: center;\n}\n\n/* Cổng DVC Quốc Gia Link & Banner Styles */\n.dvc-direct-link {\n  color: #38bdf8;\n  text-decoration: none;\n  font-weight: 500;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  word-break: break-all;\n  transition: var(--transition);\n}\n.dvc-direct-link:hover {\n  color: #7dd3fc;\n  text-decoration: underline;\n}\n\n.detail-dvc-banner {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  background: rgba(56, 189, 248, 0.08);\n  border: 1px solid rgba(56, 189, 248, 0.25);\n  border-radius: var(--radius-sm);\n  padding: 12px 16px;\n  margin: 12px 0 16px 0;\n  color: var(--text-main);\n  font-size: 0.85rem;\n}\n.detail-dvc-banner i {\n  font-size: 1.3rem;\n  color: var(--primary);\n  flex-shrink: 0;\n}\n.dvc-banner-content {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  word-break: break-all;\n}\n\n.modal-dvc-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  text-decoration: none;\n  font-size: 0.75rem;\n  font-weight: 500;\n  padding: 4px 10px;\n}\n.modal-title {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.modal-header-left {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex: 1;\n  min-width: 220px;\n}\n.modal-header-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n.modal-view-mode-toggle {\n  display: inline-flex;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: var(--radius-sm);\n  padding: 2px;\n  gap: 2px;\n}\n.modal-view-mode-toggle .btn {\n  border: none;\n  background: transparent;\n  color: var(--text-muted);\n  box-shadow: none;\n  padding: 4px 8px;\n}\n.modal-view-mode-toggle .btn.active {\n  background: var(--primary);\n  color: #0b1120;\n  font-weight: 600;\n}\n.modal-markdown-viewport {\n  padding: 24px;\n  background: #060911;\n  overflow-y: auto;\n}\n.modal-markdown-viewport pre {\n  margin: 0;\n  font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;\n  font-size: 0.85rem;\n  line-height: 1.6;\n  color: #e2e8f0;\n  white-space: pre-wrap;\n  word-break: break-word;\n  user-select: text;\n}\n\n/* =========================================================\n   QĐCB MODAL (CẤU TRÚC CHUẨN DỊCH VỤ CÔNG QUỐC GIA)\n   ========================================================= */\n.qdcb-modal-view {\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n.qdcb-excerpt-box {\n  background: linear-gradient(135deg, rgba(245, 158, 11, 0.12) 0%, rgba(15, 23, 42, 0.8) 100%);\n  border: 1px solid rgba(245, 158, 11, 0.35);\n  border-left: 4px solid #f59e0b;\n  border-radius: var(--radius-md);\n  padding: 14px 18px;\n}\n.qdcb-excerpt-label {\n  font-size: 0.72rem;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: #fbbf24;\n  font-weight: 700;\n  margin-bottom: 4px;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.qdcb-excerpt-text {\n  font-size: 0.98rem;\n  font-weight: 600;\n  color: #f8fafc;\n  line-height: 1.5;\n}\n\n.qdcb-info-card {\n  background: rgba(15, 23, 42, 0.7);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-md);\n  padding: 16px 18px;\n}\n.qdcb-info-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 12px;\n}\n.qdcb-info-cell {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  padding: 8px 12px;\n  background: rgba(0, 0, 0, 0.25);\n  border-radius: var(--radius-sm);\n  border: 1px solid rgba(255, 255, 255, 0.05);\n}\n.qdcb-info-label {\n  font-size: 0.72rem;\n  color: var(--text-dim);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  font-weight: 600;\n}\n.qdcb-info-val {\n  font-size: 0.88rem;\n  color: var(--text-main);\n  font-weight: 600;\n}\n\n.qdcb-attachments-bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 12px;\n  padding-top: 12px;\n  border-top: 1px solid rgba(255, 255, 255, 0.06);\n}\n.qdcb-file-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 5px 12px;\n  font-size: 0.8rem;\n  font-weight: 500;\n  color: #38bdf8;\n  background: rgba(56, 189, 248, 0.1);\n  border: 1px solid rgba(56, 189, 248, 0.3);\n  border-radius: var(--radius-sm);\n  text-decoration: none;\n  transition: var(--transition);\n}\n.qdcb-file-btn:hover {\n  background: rgba(56, 189, 248, 0.2);\n  color: #7dd3fc;\n}\n\n/* Tabs Danh sách TTHC thuộc QĐCB */\n.qdcb-tabs-section {\n  background: rgba(15, 23, 42, 0.65);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: var(--radius-md);\n  overflow: hidden;\n}\n.qdcb-tabs-bar {\n  display: flex;\n  gap: 4px;\n  padding: 10px 14px 0 14px;\n  background: rgba(6, 9, 19, 0.5);\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n  overflow-x: auto;\n}\n.qdcb-tab-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  padding: 9px 14px;\n  font-size: 0.84rem;\n  font-weight: 600;\n  color: var(--text-muted);\n  background: transparent;\n  border: none;\n  border-bottom: 2px solid transparent;\n  cursor: pointer;\n  white-space: nowrap;\n  transition: var(--transition);\n}\n.qdcb-tab-btn:hover {\n  color: var(--text-main);\n  background: rgba(255, 255, 255, 0.03);\n}\n.qdcb-tab-btn.active {\n  color: var(--primary);\n  border-bottom-color: var(--primary);\n  background: rgba(56, 189, 248, 0.08);\n}\n.qdcb-tab-count {\n  font-size: 0.72rem;\n  padding: 1px 7px;\n  border-radius: 9999px;\n  background: rgba(255, 255, 255, 0.08);\n  color: var(--text-muted);\n  font-family: var(--font-mono);\n}\n.qdcb-tab-btn.active .qdcb-tab-count {\n  background: rgba(56, 189, 248, 0.22);\n  color: #38bdf8;\n}\n\n.qdcb-table-wrap {\n  overflow-x: auto;\n  padding: 12px 14px;\n}\n.qdcb-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.84rem;\n}\n.qdcb-table th {\n  text-align: left;\n  padding: 10px 12px;\n  font-size: 0.75rem;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: var(--text-dim);\n  border-bottom: 1px solid rgba(255, 255, 255, 0.1);\n  white-space: nowrap;\n}\n.qdcb-table td {\n  padding: 10px 12px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n  color: var(--text-main);\n  vertical-align: middle;\n}\n.qdcb-table tbody tr:hover {\n  background: rgba(255, 255, 255, 0.03);\n}\n.qdcb-tthc-code-btn {\n  display: inline-block;\n  font-family: var(--font-mono);\n  font-size: 0.8rem;\n  font-weight: 600;\n  color: #38bdf8;\n  background: rgba(56, 189, 248, 0.12);\n  border: 1px solid rgba(56, 189, 248, 0.3);\n  padding: 3px 8px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: var(--transition);\n}\n.qdcb-tthc-code-btn:hover {\n  background: rgba(56, 189, 248, 0.25);\n  color: #fff;\n}\n.qdcb-status-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 3px 8px;\n  border-radius: 9999px;\n  font-size: 0.74rem;\n  font-weight: 600;\n  white-space: nowrap;\n}\n.qdcb-status-active {\n  background: rgba(16, 185, 129, 0.15);\n  color: #34d399;\n  border: 1px solid rgba(16, 185, 129, 0.35);\n}\n.qdcb-status-inactive {\n  background: rgba(244, 63, 94, 0.15);\n  color: #fb7185;\n  border: 1px solid rgba(244, 63, 94, 0.35);\n}\n.qdcb-empty-tab {\n  text-align: center;\n  padding: 28px 16px;\n  color: var(--text-dim);\n  font-size: 0.85rem;\n}\n\n.modal-back-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 4px 10px;\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: #cbd5e1;\n  background: rgba(255, 255, 255, 0.08);\n  border: 1px solid rgba(255, 255, 255, 0.14);\n  border-radius: 6px;\n  cursor: pointer;\n  transition: var(--transition);\n}\n.modal-back-btn:hover {\n  background: rgba(56, 189, 248, 0.2);\n  color: #38bdf8;\n  border-color: rgba(56, 189, 248, 0.4);\n}\n\n.qdcb-stats-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n}\n.qdcb-stat-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 5px 12px;\n  border-radius: 9999px;\n  font-size: 0.78rem;\n  font-weight: 600;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  color: #cbd5e1;\n}\n.qdcb-stat-pill strong {\n  font-family: var(--font-mono);\n  font-size: 0.85rem;\n}\n.qdcb-stat-new {\n  background: rgba(16, 185, 129, 0.12);\n  border-color: rgba(16, 185, 129, 0.35);\n  color: #34d399;\n}\n.qdcb-stat-edit {\n  background: rgba(56, 189, 248, 0.12);\n  border-color: rgba(56, 189, 248, 0.35);\n  color: #38bdf8;\n}\n.qdcb-stat-drop {\n  background: rgba(244, 63, 94, 0.12);\n  border-color: rgba(244, 63, 94, 0.35);\n  color: #fb7185;\n}\n\n.qdcb-table-toolbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px 14px 4px 14px;\n  flex-wrap: wrap;\n}\n.qdcb-table-search-wrap {\n  position: relative;\n  flex: 1;\n  min-width: 220px;\n}\n.qdcb-table-search-wrap i {\n  position: absolute;\n  left: 11px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--text-dim);\n  font-size: 0.85rem;\n}\n.qdcb-table-search {\n  width: 100%;\n  background: rgba(6, 9, 19, 0.7);\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  border-radius: var(--radius-sm);\n  padding: 7px 12px 7px 32px;\n  color: var(--text-main);\n  font-size: 0.83rem;\n  outline: none;\n  transition: var(--transition);\n}\n.qdcb-table-search:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.15);\n}\n\n.qdcb-copy-btn {\n  background: transparent;\n  border: none;\n  color: var(--text-dim);\n  cursor: pointer;\n  padding: 2px 5px;\n  border-radius: 4px;\n  font-size: 0.8rem;\n  transition: var(--transition);\n}\n.qdcb-copy-btn:hover {\n  color: var(--primary);\n  background: rgba(56, 189, 248, 0.12);\n}\n\n.qdcb-note-box {\n  background: rgba(56, 189, 248, 0.08);\n  border: 1px dashed rgba(56, 189, 248, 0.3);\n  border-radius: var(--radius-sm);\n  padding: 10px 14px;\n  font-size: 0.84rem;\n  color: #cbd5e1;\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n}\n.qdcb-note-box i {\n  color: #38bdf8;\n  margin-top: 2px;\n}\n";
export const EMBEDDED_APP_JS: string = "// MCP TTHC Web Application Logic\ndocument.addEventListener('DOMContentLoaded', () => {\n  const currentOrigin = window.location.origin;\n  const serverUrlInput = document.getElementById('server-url-input');\n  const apiKeyInput = document.getElementById('api-key-input');\n  const btnToggleKey = document.getElementById('btn-toggle-key-visibility');\n  const btnSaveKey = document.getElementById('btn-save-key');\n  const btnCopyUrl = document.getElementById('btn-copy-url');\n\n  const statusText = document.getElementById('system-status-text');\n  const totalCountEl = document.getElementById('header-total-count');\n  const headerLatencyPill = document.getElementById('header-latency-pill');\n  const headerLatencyVal = document.getElementById('header-latency-val');\n  const footerSpeedVal = document.getElementById('footer-speed-val');\n\n  // Navigation tabs\n  const tabButtons = document.querySelectorAll('.tab-btn');\n  const tabPanels = document.querySelectorAll('.tab-panel');\n\n  // Tool form elements\n  const selectMcpTool = document.getElementById('select-mcp-tool');\n  const toolForm = document.getElementById('tool-params-form');\n  const btnExecuteTool = document.getElementById('btn-execute-tool');\n  const btnExecuteText = document.getElementById('btn-execute-text');\n  const executeSpinner = document.getElementById('execute-spinner');\n  const executionTimeBadge = document.getElementById('execution-time');\n\n  // Result view elements\n  const btnViewRendered = document.getElementById('btn-view-rendered');\n  const btnViewMarkdown = document.getElementById('btn-view-markdown');\n  const btnViewJson = document.getElementById('btn-view-json');\n  const btnCopyResult = document.getElementById('btn-copy-result');\n\n  const viewportRendered = document.getElementById('viewport-rendered');\n  const viewportMarkdown = document.getElementById('viewport-markdown');\n  const viewportJson = document.getElementById('viewport-json');\n\n  // Client Config Tab\n  const clientTabs = document.querySelectorAll('.client-tab');\n  const configFileLabel = document.getElementById('config-file-label');\n  const configCodeDisplay = document.getElementById('config-code-display');\n  const btnCopyConfig = document.getElementById('btn-copy-config');\n\n  // Modal & Export Markdown\n  const modal = document.getElementById('detail-modal');\n  const modalTitle = document.getElementById('modal-tthc-title');\n  const modalBody = document.getElementById('modal-tthc-body');\n  const btnCloseModal = document.getElementById('btn-close-modal');\n  const modalViewToggle = document.getElementById('modal-view-mode-toggle');\n  const btnModalModeRendered = document.getElementById('btn-modal-mode-rendered');\n  const btnModalModeMarkdown = document.getElementById('btn-modal-mode-markdown');\n  const btnModalCopyMd = document.getElementById('btn-modal-copy-md');\n  const btnModalDownloadMd = document.getElementById('btn-modal-download-md');\n  const modalMarkdownViewport = document.getElementById('modal-tthc-markdown-viewport');\n  const modalMarkdownCode = document.getElementById('modal-tthc-markdown-code');\n\n  // State\n  let currentRawResult = null;\n  let currentMarkdownResult = '';\n  let currentModalMarkdown = '';\n  let currentModalCode = '';\n  let activeClientConfig = 'cursor';\n  let serverAuthRequired = false;\n\n  // 1. Initialize Server URL & API Key (Đọc từ URL ?api-key=... / ?key=... hoặc localStorage)\n  serverUrlInput.value = currentOrigin;\n  const urlParams = new URLSearchParams(window.location.search);\n  const urlApiKey =\n    urlParams.get('api-key') ||\n    urlParams.get('key') ||\n    urlParams.get('apiKey') ||\n    urlParams.get('api_key') ||\n    '';\n  const savedKey = localStorage.getItem('mcp_tthc_api_key');\n  if (urlApiKey) {\n    apiKeyInput.value = urlApiKey;\n    try { localStorage.setItem('mcp_tthc_api_key', urlApiKey); } catch {}\n  } else if (savedKey) {\n    apiKeyInput.value = savedKey;\n  } else {\n    apiKeyInput.value = '';\n  }\n\n  // Tự động cập nhật năm hiện hành cho footer\n  const currentYearEl = document.getElementById('current-year');\n  if (currentYearEl) {\n    currentYearEl.textContent = new Date().getFullYear().toString();\n  }\n\n  function getActiveApiKey() {\n    return apiKeyInput.value.trim();\n  }\n\n  // Cập nhật cấu hình ngay khi người dùng gõ phím\n  apiKeyInput.addEventListener('input', () => {\n    updateClientConfigs();\n  });\n\n  // Toggle API key visibility\n  btnToggleKey.addEventListener('click', () => {\n    if (apiKeyInput.type === 'password') {\n      apiKeyInput.type = 'text';\n      btnToggleKey.innerHTML = '<i class=\"bi bi-eye-slash\"></i>';\n    } else {\n      apiKeyInput.type = 'password';\n      btnToggleKey.innerHTML = '<i class=\"bi bi-eye\"></i>';\n    }\n  });\n\n  // Save API key\n  btnSaveKey.addEventListener('click', () => {\n    const key = apiKeyInput.value.trim();\n    if (key) {\n      localStorage.setItem('mcp_tthc_api_key', key);\n      showToast('Đã lưu khóa API an toàn trong trình duyệt!');\n    } else {\n      localStorage.removeItem('mcp_tthc_api_key');\n      showToast('Đã xóa khóa API đã lưu.');\n    }\n    updateClientConfigs();\n  });\n\n  // Copy server URL\n  btnCopyUrl.addEventListener('click', () => {\n    navigator.clipboard.writeText(currentOrigin);\n    showToast('Đã sao chép URL Server!');\n  });\n\n  // Helper: Đã tắt hiển thị tốc độ phản hồi / độ trễ (latency ms) theo yêu cầu giao diện\n  function updateLatencyDisplay(_latencyMs) {}\n\n  // 2. Health check & Query Real Count (Không dùng mockup) & Đo tốc độ kết nối\n  async function checkHealth() {\n    const startTime = performance.now();\n    try {\n      totalCountEl.textContent = '...';\n      const res = await fetch(`${currentOrigin}/api/health?t=${Date.now()}`);\n      const latency = Math.round(performance.now() - startTime);\n\n      if (res.ok) {\n        const data = await res.json();\n        const connCount = Number(data.connections ?? data.active_connections ?? 1);\n        statusText.textContent = `${connCount} kết nối`;\n        const statusIndicator = document.querySelector('.status-indicator');\n        if (statusIndicator) {\n          statusIndicator.title = `Máy chủ hoạt động • ${connCount} kết nối đang hoạt động`;\n        }\n        updateLatencyDisplay(latency);\n\n        if (data.app_version) {\n          const vBadge = document.getElementById('app-version-badge');\n          if (vBadge) vBadge.textContent = `v${data.app_version}`;\n          const fBadge = document.getElementById('footer-version-badge');\n          if (fBadge) fBadge.textContent = `v${data.app_version}`;\n        }\n\n        // Lấy số lượng thực tế từ kết quả truy vấn máy chủ\n        const realCount =\n          data.total_records ||\n          data.data_version?.total_records ||\n          data.version?.total_records;\n        if (realCount && Number(realCount) > 0) {\n          const formatted = Number(realCount).toLocaleString('vi-VN');\n          totalCountEl.textContent = formatted;\n        } else {\n          totalCountEl.textContent = '---';\n        }\n\n        // Lấy thời gian cập nhật dữ liệu dựa vào version url\n        const rawUpdated =\n          data.last_updated ||\n          data.data_version?.last_updated ||\n          data.version?.last_updated;\n        const updatedValEl = document.getElementById('header-updated-val');\n        const updatedBadgeEl = document.getElementById('header-updated-badge');\n        if (updatedValEl) {\n          if (rawUpdated) {\n            try {\n              const d = new Date(rawUpdated);\n              if (!isNaN(d.getTime())) {\n                const day = String(d.getDate()).padStart(2, '0');\n                const month = String(d.getMonth() + 1).padStart(2, '0');\n                const year = d.getFullYear();\n                const hours = String(d.getHours()).padStart(2, '0');\n                const minutes = String(d.getMinutes()).padStart(2, '0');\n                updatedValEl.textContent = `${day}/${month}/${year}`;\n                if (updatedBadgeEl) {\n                  updatedBadgeEl.title = `Thời gian cập nhật dữ liệu: ${day}/${month}/${year} ${hours}:${minutes} (CSDL DVCQG)`;\n                }\n              } else {\n                updatedValEl.textContent = String(rawUpdated).slice(0, 10);\n              }\n            } catch {\n              updatedValEl.textContent = String(rawUpdated).slice(0, 10);\n            }\n          } else {\n            updatedValEl.textContent = '---';\n          }\n        }\n\n        serverAuthRequired = Boolean(data.authRequired);\n        const noticeEl = document.getElementById('auth-notice-text');\n        if (noticeEl) {\n          if (serverAuthRequired) {\n            noticeEl.innerHTML = 'Bảo mật API: <b>BẬT</b>. Chỉ thực thi và hiển thị khi bạn nhập <code>API_KEY</code>.';\n          } else {\n            noticeEl.innerHTML = 'Bảo mật API: <i>Tùy chọn</i> (Chế độ phát triển mở).';\n          }\n        }\n        updateClientConfigs();\n      } else {\n        statusText.textContent = 'Máy chủ ngoại tuyến';\n        totalCountEl.textContent = '---';\n        const updatedValEl = document.getElementById('header-updated-val');\n        if (updatedValEl) updatedValEl.textContent = '---';\n        if (headerLatencyPill) headerLatencyPill.style.display = 'none';\n        if (footerSpeedVal) footerSpeedVal.textContent = 'Mất kết nối';\n      }\n    } catch {\n      statusText.textContent = 'Không kết nối được';\n      totalCountEl.textContent = '---';\n      const updatedValEl = document.getElementById('header-updated-val');\n      if (updatedValEl) updatedValEl.textContent = '---';\n      if (headerLatencyPill) headerLatencyPill.style.display = 'none';\n      if (footerSpeedVal) footerSpeedVal.textContent = 'Ngoại tuyến';\n    }\n  }\n\n  checkHealth();\n  setInterval(checkHealth, 30000);\n\n  // 3. Tab Navigation\n  tabButtons.forEach(btn => {\n    btn.addEventListener('click', () => {\n      tabButtons.forEach(b => b.classList.remove('active'));\n      tabPanels.forEach(p => p.classList.remove('active'));\n\n      btn.classList.add('active');\n      const targetId = `panel-${btn.dataset.tab}`;\n      const targetPanel = document.getElementById(targetId);\n      if (targetPanel) targetPanel.classList.add('active');\n\n      if (btn.dataset.tab === 'connect') {\n        updateClientConfigs();\n      }\n    });\n  });\n\n  // 4. Dynamic Tool Parameters Form Switching\n  const paramGroups = {\n    tra_cuu_quyet_dinh_cong_bo: document.getElementById('params-tra_cuu_quyet_dinh_cong_bo'),\n    chi_tiet_quyet_dinh_cong_bo: document.getElementById('params-chi_tiet_quyet_dinh_cong_bo'),\n    tra_cuu_tthc_gia_lai: document.getElementById('params-tra_cuu_tthc_gia_lai'),\n    tra_cuu_tthc_noi_bo_gia_lai: document.getElementById('params-tra_cuu_tthc_noi_bo_gia_lai'),\n    tra_cuu_tthc_noi_bo: document.getElementById('params-tra_cuu_tthc_noi_bo'),\n    tra_cuu_theo_ma_tthc: document.getElementById('params-tra_cuu_theo_ma_tthc'),\n    goi_y_thu_tuc_lien_quan: document.getElementById('params-goi_y_thu_tuc_lien_quan'),\n    tim_kiem_theo_ten_tthc: document.getElementById('params-tim_kiem_theo_ten_tthc'),\n    loc_theo_cap_thuc_hien: document.getElementById('params-loc_theo_cap_thuc_hien'),\n    loc_theo_linh_vuc: document.getElementById('params-loc_theo_linh_vuc'),\n    tim_kiem_tong_hop: document.getElementById('params-tim_kiem_tong_hop'),\n    thong_tin_mcp_server: null\n  };\n\n  const paginationControls = document.getElementById('common-pagination-controls');\n\n  selectMcpTool.addEventListener('change', () => {\n    const selected = selectMcpTool.value;\n    Object.keys(paramGroups).forEach(key => {\n      const el = paramGroups[key];\n      if (el) el.style.display = key === selected ? 'block' : 'none';\n    });\n\n    if (\n      selected === 'chi_tiet_quyet_dinh_cong_bo' ||\n      selected === 'tra_cuu_theo_ma_tthc' ||\n      selected === 'goi_y_thu_tuc_lien_quan' ||\n      selected === 'thong_tin_mcp_server'\n    ) {\n      paginationControls.style.display = 'none';\n    } else {\n      paginationControls.style.display = 'flex';\n    }\n  });\n\n  // Quick Chips\n  document.querySelectorAll('.btn-chip[data-fill-code]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const code = chip.dataset.fillCode;\n      document.getElementById('input-ma-tthc').value = code;\n    });\n  });\n\n  document.querySelectorAll('.btn-chip[data-fill-theme]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const theme = chip.dataset.fillTheme;\n      const themeInput = document.getElementById('input-related-theme');\n      if (themeInput) themeInput.value = theme;\n    });\n  });\n\n  document.querySelectorAll('.btn-chip[data-fill-query]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const q = chip.dataset.fillQuery;\n      document.getElementById('input-ten-tthc').value = q;\n    });\n  });\n\n  document.querySelectorAll('.btn-chip[data-fill-agency]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const val = chip.dataset.fillAgency;\n      document.getElementById('input-co-quan').value = val;\n    });\n  });\n\n  document.querySelectorAll('.btn-chip[data-fill-banhanh]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const val = chip.dataset.fillBanhanh;\n      document.getElementById('input-co-quan-ban-hanh').value = val;\n    });\n  });\n\n  document.querySelectorAll('.btn-chip[data-fill-linhvuc]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const val = chip.dataset.fillLinhvuc;\n      const selectEl = document.getElementById('select-linh-vuc');\n      if (selectEl) {\n        selectEl.value = val;\n      }\n    });\n  });\n\n  // Quick Chips Gia Lai\n  document.querySelectorAll('.btn-chip[data-fill-gl-cq]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cq = chip.dataset.fillGlCq;\n      const inputEl = document.getElementById('input-gialai-co-quan');\n      if (inputEl) inputEl.value = cq;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-gl-cap]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cap = chip.dataset.fillGlCap;\n      const selectEl = document.getElementById('select-gialai-cap');\n      if (selectEl) selectEl.value = cap;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-gl-code]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const code = chip.dataset.fillGlCode;\n      const inputEl = document.getElementById('input-gialai-code');\n      if (inputEl) inputEl.value = code;\n    });\n  });\n\n  document.querySelectorAll('.btn-chip[data-fill-nb-cq]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cq = chip.dataset.fillNbCq;\n      const inputEl = document.getElementById('input-noibo-co-quan');\n      if (inputEl) inputEl.value = cq;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-nb-lv]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const lv = chip.dataset.fillNbLv;\n      const inputEl = document.getElementById('input-noibo-linh-vuc');\n      if (inputEl) inputEl.value = lv;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-nb-cap]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cap = chip.dataset.fillNbCap;\n      const selectEl = document.getElementById('select-noibo-cap');\n      if (selectEl) selectEl.value = cap;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-nb-code]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const code = chip.dataset.fillNbCode;\n      const inputEl = document.getElementById('input-noibo-code');\n      if (inputEl) inputEl.value = code;\n    });\n  });\n\n  // Quick chips cho TTHC nội bộ Gia Lai\n  document.querySelectorAll('.btn-chip[data-fill-nbgl-cq]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cq = chip.dataset.fillNbglCq;\n      const inputEl = document.getElementById('input-noibo-gl-co-quan');\n      if (inputEl) inputEl.value = cq;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-nbgl-lv]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const lv = chip.dataset.fillNbglLv;\n      const inputEl = document.getElementById('input-noibo-gl-linh-vuc');\n      if (inputEl) inputEl.value = lv;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-nbgl-cap]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cap = chip.dataset.fillNbglCap;\n      const selectEl = document.getElementById('select-noibo-gl-cap');\n      if (selectEl) selectEl.value = cap;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-nbgl-code]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const code = chip.dataset.fillNbglCode;\n      const inputEl = document.getElementById('input-noibo-gl-code');\n      if (inputEl) inputEl.value = code;\n    });\n  });\n\n  // Quick chips cho QĐCB\n  document.querySelectorAll('.btn-chip[data-fill-qdcb-so]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const so = chip.dataset.fillQdcbSo;\n      const inputEl = document.getElementById('input-qdcb-so');\n      if (inputEl && so !== undefined) inputEl.value = so;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-qdcb-coquan]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const cq = chip.dataset.fillQdcbCoquan;\n      const inputEl = document.getElementById('input-qdcb-coquan');\n      if (inputEl && cq !== undefined) inputEl.value = cq;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-qdcb-monthly]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const val = chip.dataset.fillQdcbMonthly;\n      const selectEl = document.getElementById('select-qdcb-monthly');\n      if (selectEl && val !== undefined) selectEl.value = val;\n    });\n  });\n  document.querySelectorAll('.btn-chip[data-fill-qdcb-detail]').forEach(chip => {\n    chip.addEventListener('click', () => {\n      const val = chip.dataset.fillQdcbDetail;\n      const inputEl = document.getElementById('input-qdcb-detail-id');\n      if (inputEl && val !== undefined) inputEl.value = val;\n    });\n  });\n\n  // 5. Tool Execution via MCP JSON-RPC\n  toolForm.addEventListener('submit', async e => {\n    e.preventDefault();\n    await executeCurrentTool();\n  });\n\n  async function executeCurrentTool(customTool, customArgs) {\n    const toolName = customTool || selectMcpTool.value;\n    const apiKey = getActiveApiKey();\n    const limit = parseInt(document.getElementById('input-limit')?.value || '10', 10);\n    const page = parseInt(document.getElementById('input-page')?.value || '1', 10);\n\n    let args = customArgs || {};\n    if (!customArgs) {\n      if (toolName === 'tra_cuu_quyet_dinh_cong_bo' || toolName === 'tra_cuu_qdcb' || toolName === 'tim_kiem_qdcb') {\n        const kw = document.getElementById('input-qdcb-keyword')?.value.trim();\n        const so = document.getElementById('input-qdcb-so')?.value.trim();\n        const cq = document.getElementById('input-qdcb-coquan')?.value.trim();\n        const lv = document.getElementById('input-qdcb-linhvuc')?.value.trim();\n        const namVal = document.getElementById('input-qdcb-nam')?.value.trim();\n        const thangVal = document.getElementById('input-qdcb-thang')?.value.trim();\n        const isMonthly = document.getElementById('select-qdcb-monthly')?.value === 'true';\n        args = {\n          tu_khoa: kw || undefined,\n          so_quyet_dinh: so || undefined,\n          co_quan_ban_hanh: cq || undefined,\n          linh_vuc: lv || undefined,\n          nam: namVal ? parseInt(namVal, 10) : undefined,\n          thang: thangVal || undefined,\n          moi_trong_thang: isMonthly,\n          limit,\n          page,\n          dinh_dang: 'markdown'\n        };\n      } else if (toolName === 'chi_tiet_quyet_dinh_cong_bo' || toolName === 'chi_tiet_qdcb' || toolName === 'lay_qdcb_theo_so') {\n        const id = document.getElementById('input-qdcb-detail-id')?.value.trim();\n        const format = document.getElementById('select-qdcb-detail-format')?.value || 'markdown';\n        args = {\n          so_hoac_id_qdcb: id,\n          dinh_dang: format\n        };\n      } else if (toolName === 'tra_cuu_tthc_gia_lai' || toolName === 'tthc_gia_lai') {\n        const kw = document.getElementById('input-gialai-keyword')?.value.trim();\n        const code = document.getElementById('input-gialai-code')?.value.trim();\n        const cap = document.getElementById('select-gialai-cap')?.value;\n        const coQuan = document.getElementById('input-gialai-co-quan')?.value.trim();\n        const isDetail = document.getElementById('select-gialai-detail')?.value === 'true';\n        args = {\n          tu_khoa: kw || undefined,\n          ma_tthc: code || undefined,\n          cap_thuc_hien: cap || 'tat_ca',\n          co_quan_thuc_hien: coQuan || undefined,\n          chi_tiet: isDetail,\n          limit,\n          page,\n          dinh_dang: 'markdown'\n        };\n      } else if (toolName === 'tra_cuu_tthc_noi_bo_gia_lai' || toolName === 'tthc_noi_bo_gia_lai' || toolName === 'tthc_gia_lai_noi_bo') {\n        const kw = document.getElementById('input-noibo-gl-keyword')?.value.trim();\n        const code = document.getElementById('input-noibo-gl-code')?.value.trim();\n        const cap = document.getElementById('select-noibo-gl-cap')?.value;\n        const coQuan = document.getElementById('input-noibo-gl-co-quan')?.value.trim();\n        const nhom = document.getElementById('select-noibo-gl-nhom')?.value;\n        const linhVuc = document.getElementById('input-noibo-gl-linh-vuc')?.value.trim();\n        const isDetail = document.getElementById('select-noibo-gl-detail')?.value === 'true';\n        args = {\n          tu_khoa: kw || undefined,\n          ma_tthc: code || undefined,\n          cap_thuc_hien: cap || 'tat_ca',\n          co_quan: coQuan || undefined,\n          nhom_noi_bo: nhom || 'tat_ca',\n          linh_vuc: linhVuc || undefined,\n          chi_tiet: isDetail,\n          limit,\n          page,\n          dinh_dang: 'markdown'\n        };\n      } else if (toolName === 'tra_cuu_tthc_noi_bo' || toolName === 'tthc_noi_bo') {\n        const kw = document.getElementById('input-noibo-keyword')?.value.trim();\n        const code = document.getElementById('input-noibo-code')?.value.trim();\n        const cap = document.getElementById('select-noibo-cap')?.value;\n        const coQuan = document.getElementById('input-noibo-co-quan')?.value.trim();\n        const nhom = document.getElementById('select-noibo-nhom')?.value;\n        const linhVuc = document.getElementById('input-noibo-linh-vuc')?.value.trim();\n        const isDetail = document.getElementById('select-noibo-detail')?.value === 'true';\n        args = {\n          tu_khoa: kw || undefined,\n          ma_tthc: code || undefined,\n          cap_thuc_hien: cap || 'tat_ca',\n          co_quan: coQuan || undefined,\n          nhom_noi_bo: nhom || 'tat_ca',\n          linh_vuc: linhVuc || undefined,\n          chi_tiet: isDetail,\n          limit,\n          page,\n          dinh_dang: 'markdown'\n        };\n      } else if (toolName === 'tra_cuu_theo_ma_tthc' || toolName === 'chi_tiet_tthc') {\n        const phanMuc = document.getElementById('select-detail-phan-muc')?.value || 'tat_ca';\n        const dinhDang = document.getElementById('select-detail-format')?.value || 'markdown';\n        args = {\n          ma_tthc: document.getElementById('input-ma-tthc').value.trim(),\n          phan_muc: phanMuc,\n          dinh_dang: dinhDang\n        };\n      } else if (toolName === 'goi_y_thu_tuc_lien_quan' || toolName === 'related_procedures') {\n        const relTthc = document.getElementById('input-related-tthc')?.value.trim();\n        const relTheme = document.getElementById('input-related-theme')?.value.trim();\n        const relLimit = parseInt(document.getElementById('select-related-limit')?.value || '6', 10);\n        const relFormat = document.getElementById('select-related-format')?.value || 'markdown';\n        args = {\n          ma_hoac_ten_tthc: relTthc || undefined,\n          chu_de: relTheme || undefined,\n          limit: relLimit,\n          dinh_dang: relFormat\n        };\n      } else if (toolName === 'tim_kiem_theo_ten_tthc') {\n        args = {\n          ten_tthc: document.getElementById('input-ten-tthc').value.trim(),\n          limit,\n          page\n        };\n      } else if (toolName === 'loc_theo_cap_thuc_hien') {\n        const cap = document.getElementById('select-cap-thuc-hien').value;\n        const kw = document.getElementById('input-cap-keyword').value.trim();\n        args = { cap_thuc_hien: cap, tu_khoa: kw || undefined, limit, page };\n      } else if (toolName === 'loc_theo_linh_vuc') {\n        const lv = document.getElementById('select-linh-vuc').value;\n        const kw = document.getElementById('input-linh-vuc-keyword').value.trim();\n        args = { linh_vuc: lv, tu_khoa: kw || undefined, limit, page };\n      } else if (toolName === 'tim_kiem_tong_hop') {\n        const kw = document.getElementById('adv-keyword').value.trim();\n        const cap = document.getElementById('adv-cap').value.trim();\n        const lv = document.getElementById('adv-linh-vuc').value.trim();\n        const cq = document.getElementById('adv-co-quan').value.trim();\n        const phi = document.getElementById('adv-phi').value;\n        args = {\n          tu_khoa: kw || undefined,\n          cap_thuc_hien: cap || undefined,\n          linh_vuc: lv || undefined,\n          co_quan: cq || undefined,\n          co_thu_phi: phi === '' ? undefined : phi === 'true',\n          limit,\n          page\n        };\n      } else if (toolName === 'thong_tin_mcp_server') {\n        args = {};\n      }\n    }\n\n    // Kiểm tra nếu server yêu cầu API Key mà người dùng chưa nhập\n    if (serverAuthRequired && !apiKey) {\n      renderError('Yêu cầu bảo mật: Máy chủ đã bật xác thực API Key. Vui lòng nhập API Key của bạn vào ô \"Khóa API Key\" ở phía trên để thực thi lệnh.');\n      return;\n    }\n\n    // Set UI loading state\n    btnExecuteTool.disabled = true;\n    executeSpinner.style.display = 'inline-block';\n    btnExecuteText.textContent = 'Đang thực thi...';\n    executionTimeBadge.style.display = 'none';\n\n    const startTime = performance.now();\n\n    // Construct MCP JSON-RPC Payload\n    const jsonRpcPayload = {\n      jsonrpc: '2.0',\n      id: Date.now(),\n      method: 'tools/call',\n      params: {\n        name: toolName,\n        arguments: args\n      }\n    };\n\n    const targetUrl = apiKey\n      ? `${currentOrigin}/mcp?api-key=${encodeURIComponent(apiKey)}`\n      : `${currentOrigin}/mcp`;\n\n    try {\n      const response = await fetch(targetUrl, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(jsonRpcPayload)\n      });\n\n      const elapsed = Math.round(performance.now() - startTime);\n      executionTimeBadge.textContent = `${elapsed}ms`;\n      executionTimeBadge.style.display = 'inline-block';\n      updateLatencyDisplay(elapsed);\n\n      if (!response.ok) {\n        if (response.status === 401) {\n          const errData = await response.json();\n          renderError(`401 Unauthorized: ${errData.message || 'Sai API Key'}`);\n          return;\n        }\n        throw new Error(`HTTP ${response.status}: ${response.statusText}`);\n      }\n\n      const result = await response.json();\n      currentRawResult = result;\n\n      // Extract markdown text from MCP standard response\n      if (result.result && result.result.content && result.result.content[0]) {\n        currentMarkdownResult = stripInternalIds(result.result.content[0].text || '');\n      } else if (result.error) {\n        currentMarkdownResult = `Lỗi MCP: ${result.error.message || JSON.stringify(result.error)}`;\n      } else {\n        currentMarkdownResult = JSON.stringify(result, null, 2);\n      }\n\n      // Update Viewports\n      viewportMarkdown.querySelector('code').textContent = currentMarkdownResult;\n      viewportJson.querySelector('code').textContent = JSON.stringify(result, null, 2);\n\n      // Render Rich View\n      renderRichView(toolName, currentMarkdownResult);\n    } catch (err) {\n      renderError(err.message);\n    } finally {\n      btnExecuteTool.disabled = false;\n      executeSpinner.style.display = 'none';\n      btnExecuteText.innerHTML = '<i class=\"bi bi-play-circle-fill\"></i> Gọi MCP Tool Call';\n    }\n  }\n\n  function renderError(message) {\n    viewportRendered.innerHTML = `\n      <div class=\"empty-state\">\n        <div class=\"empty-icon\" style=\"color: #f43f5e;\"><i class=\"bi bi-exclamation-triangle-fill\"></i></div>\n        <h3 style=\"color: #f43f5e;\">Lỗi Thực Thi</h3>\n        <p>${escapeHtml(message)}</p>\n        <p style=\"margin-top: 10px; font-size: 0.8rem; color: var(--text-dim);\">\n          Kiểm tra lại xem API Key trên URL đã trùng khớp với biến môi trường <code>API_KEY</code> chưa.\n        </p>\n      </div>\n    `;\n    viewportMarkdown.querySelector('code').textContent = message;\n    viewportJson.querySelector('code').textContent = JSON.stringify({ error: message }, null, 2);\n  }\n\n  function stripInternalIds(text) {\n    if (!text || typeof text !== 'string') return text;\n    return text\n      .split('\\n')\n      .filter(line => {\n        const trimmed = line.trim();\n        return (\n          !trimmed.startsWith('- **ID Hệ thống**:') &&\n          !trimmed.startsWith('- **ID hệ thống**:') &&\n          !trimmed.includes('ID Hệ thống:')\n        );\n      })\n      .map(line => line.replace(/\\s*\\|\\s*\\*\\*ID\\*\\*:\\s*`[^`]+`/g, ''))\n      .join('\\n');\n  }\n\n  function renderRichView(toolName, markdownText) {\n    if (toolName === 'chi_tiet_tthc' || toolName === 'tra_cuu_theo_ma_tthc' || toolName === 'thong_tin_mcp_server') {\n      renderProcedureDetail(markdownText);\n    } else if (\n      toolName === 'chi_tiet_quyet_dinh_cong_bo' ||\n      toolName === 'chi_tiet_qdcb' ||\n      toolName === 'lay_qdcb_theo_so'\n    ) {\n      renderProcedureDetail(markdownText);\n      // Nếu là chi tiết QĐCB, trích xuất ID/Số QĐ và thêm nút mở Modal chuẩn DVCQG\n      const matchQd = markdownText.match(/\\*\\*ID QĐCB\\*\\*:\\s*`([^`]+)`/) || markdownText.match(/\\*\\*Số Quyết định\\*\\*:\\s*`([^`]+)`/);\n      if (matchQd && matchQd[1]) {\n        const qdId = matchQd[1];\n        const banner = document.createElement('div');\n        banner.className = 'detail-dvc-banner';\n        banner.style.cssText = 'justify-content: space-between; margin-bottom: 14px; background: rgba(245, 158, 11, 0.12); border-color: rgba(245, 158, 11, 0.35);';\n        banner.innerHTML = `\n          <div style=\"display:flex; align-items:center; gap:10px;\">\n            <i class=\"bi bi-layout-text-window-reverse\" style=\"color:#fbbf24;\"></i>\n            <span>Xem giao diện bảng QĐCB chuẩn Cổng Dịch vụ công Quốc gia</span>\n          </div>\n          <button type=\"button\" class=\"btn btn-primary btn-xs btn-view-qdcb-detail\" data-qdcb-id=\"${escapeHtml(qdId)}\">\n            <i class=\"bi bi-window-fullscreen\"></i> Mở Modal QĐCB\n          </button>\n        `;\n        viewportRendered.prepend(banner);\n        banner.querySelector('.btn-view-qdcb-detail')?.addEventListener('click', () => openQDCBModal(qdId));\n      }\n    } else {\n      renderProcedureList(markdownText);\n    }\n  }\n\n  function renderProcedureList(markdownText) {\n    const lines = markdownText.split('\\n');\n    let html = '';\n\n    let inItem = false;\n    let currentItem = {};\n\n    for (let i = 0; i < lines.length; i++) {\n      const line = lines[i].trim();\n\n      if (line.startsWith('## ')) {\n        html += `<h3 class=\"section-title\" style=\"margin-bottom: 8px;\"><i class=\"bi bi-card-checklist\"></i> ${escapeHtml(line.slice(3))}</h3>`;\n      } else if (line.startsWith('> ')) {\n        html += `<p class=\"section-desc\" style=\"margin-bottom: 16px;\">${escapeHtml(line.slice(2))}</p>`;\n      } else if (line.startsWith('### ')) {\n        if (inItem) {\n          html += buildItemCard(currentItem);\n          currentItem = {};\n        }\n        inItem = true;\n        currentItem.title = line.slice(4);\n        if (currentItem.title.includes('Quyết định số')) {\n          currentItem.isQdcb = true;\n          const mSo = currentItem.title.match(/`([^`]+)`/);\n          if (mSo) currentItem.code = mSo[1];\n        }\n      } else if (line.startsWith('- **Mã TTHC**:')) {\n        const matchCode = line.match(/`([^`]+)`/);\n        if (matchCode) currentItem.code = matchCode[1];\n      } else if (line.startsWith('- **ID QĐCB**:')) {\n        currentItem.isQdcb = true;\n        const matchId = line.match(/`([^`]+)`/);\n        if (matchId) currentItem.qdcbId = matchId[1];\n      } else if (line.startsWith('- **Cấp thực hiện**:') || line.startsWith('- **Ngày ban hành**:')) {\n        currentItem.meta1 = line;\n      } else if (line.startsWith('- **Cơ quan thực hiện**:') || line.startsWith('- **Trích yếu**:') || line.startsWith('- **Lĩnh vực**:')) {\n        if (!currentItem.meta2) currentItem.meta2 = line;\n        else currentItem.meta2 += ' | ' + line.replace(/^- /, '');\n      } else if (line.startsWith('- **Link DVC') || line.startsWith('- **Link gốc DVCQG**:')) {\n        const matchLink = line.match(/\\((https?:\\/\\/[^)]+)\\)/);\n        if (matchLink) currentItem.targetLink = matchLink[1];\n      }\n    }\n\n    if (inItem) {\n      html += buildItemCard(currentItem);\n    }\n\n    if (!html) {\n      html = `<pre class=\"viewport-code\"><code>${escapeHtml(markdownText)}</code></pre>`;\n    }\n\n    viewportRendered.innerHTML = html;\n\n    // Attach click events to \"Xem chi tiết\" buttons\n    viewportRendered.querySelectorAll('.btn-view-detail').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const code = btn.dataset.code;\n        openDetailModal(code);\n      });\n    });\n\n    // Attach click events to \"Xem chi tiết QĐCB\" buttons\n    viewportRendered.querySelectorAll('.btn-view-qdcb-detail').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const qdcbId = btn.dataset.qdcbId;\n        openQDCBModal(qdcbId);\n      });\n    });\n  }\n\n  function buildItemCard(item) {\n    const targetLink = item.targetLink || (item.id\n      ? `https://dichvucong.gov.vn/thu-tuc-hanh-chinh/${encodeURIComponent(item.id)}`\n      : '');\n\n    if (item.isQdcb) {\n      const qdKey = item.qdcbId || item.code || '';\n      return `\n        <div class=\"rendered-item-card\" style=\"border-left: 3px solid #f59e0b;\">\n          <div class=\"rendered-item-header\">\n            <h4 class=\"rendered-item-title\">${escapeHtml(item.title || 'Quyết định công bố')}</h4>\n            ${item.code ? `<span class=\"meta-pill meta-pill-qdcb\" style=\"font-size:0.75rem; padding:2px 8px;\">${escapeHtml(item.code)}</span>` : ''}\n          </div>\n          <div class=\"rendered-item-meta\">\n            ${item.meta1 ? `<div>${item.meta1.replace(/- \\*\\*/g, '<span><strong>').replace(/\\*\\*/g, '</strong></span>')}</div>` : ''}\n            ${item.meta2 ? `<div>${item.meta2.replace(/- \\*\\*/g, '<span><strong>').replace(/\\*\\*/g, '</strong></span>')}</div>` : ''}\n          </div>\n          <div class=\"rendered-item-actions\">\n            ${targetLink ? `\n            <a href=\"${targetLink}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-xs\" title=\"Xem văn bản trên Cổng Dịch vụ công Quốc gia\">\n              <i class=\"bi bi-box-arrow-up-right\"></i> Xem trên DVCQG\n            </a>\n            ` : ''}\n            <button class=\"btn btn-primary btn-xs btn-view-qdcb-detail\" data-qdcb-id=\"${escapeHtml(qdKey)}\">\n              <i class=\"bi bi-eye\"></i> Chi tiết QĐCB\n            </button>\n          </div>\n        </div>\n      `;\n    }\n\n    return `\n      <div class=\"rendered-item-card\">\n        <div class=\"rendered-item-header\">\n          <h4 class=\"rendered-item-title\">${escapeHtml(item.title || 'Thủ tục hành chính')}</h4>\n          ${item.code ? `<span class=\"badge badge-primary\">${escapeHtml(item.code)}</span>` : ''}\n        </div>\n        <div class=\"rendered-item-meta\">\n          ${item.meta1 ? `<div>${item.meta1.replace(/- \\*\\*/g, '<span><strong>').replace(/\\*\\*/g, '</strong></span>')}</div>` : ''}\n          ${item.meta2 ? `<div>${item.meta2.replace(/- \\*\\*/g, '<span><strong>').replace(/\\*\\*/g, '</strong></span>')}</div>` : ''}\n        </div>\n        <div class=\"rendered-item-actions\">\n          ${targetLink ? `\n          <a href=\"${targetLink}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-xs\" title=\"Mở trang nộp hồ sơ trên Cổng Dịch vụ công Quốc gia\">\n            <i class=\"bi bi-send-fill\"></i> Nộp hồ sơ\n          </a>\n          ` : ''}\n          <button class=\"btn btn-primary btn-xs btn-view-detail\" data-code=\"${escapeHtml(item.code || '')}\">\n            <i class=\"bi bi-eye\"></i> Xem chi tiết\n          </button>\n        </div>\n      </div>\n    `;\n  }\n\n  function formatDetailHtml(markdownText) {\n    const rawLines = markdownText.split('\\n');\n    let titleText = '';\n    let firstSectionIdx = -1;\n\n    // Tìm dòng section đầu tiên (## hoặc ###) và tiêu đề chính\n    for (let i = 0; i < rawLines.length; i++) {\n      const line = rawLines[i].trim();\n      if (!titleText && line.startsWith('# ')) {\n        titleText = line.slice(2).trim();\n      } else if (line.startsWith('## ') || line.startsWith('### ')) {\n        firstSectionIdx = i;\n        break;\n      }\n    }\n\n    const metaMap = {};\n    const otherMetaLines = [];\n    const metaEndIdx = firstSectionIdx === -1 ? rawLines.length : firstSectionIdx;\n\n    // Bóc tách metadata từ các dòng trước section đầu tiên\n    for (let i = 0; i < metaEndIdx; i++) {\n      const line = rawLines[i].trim();\n      if (!line || line.startsWith('# ')) continue;\n\n      if (line.startsWith('- ')) {\n        const content = line.slice(2).trim();\n        // Bỏ qua ID nội bộ\n        if (\n          content.includes('ID Hệ thống') ||\n          content.includes('ID hệ thống') ||\n          content.startsWith('**ID Hệ thống**') ||\n          content.startsWith('**ID**:') ||\n          content.startsWith('**ID**')\n        ) {\n          continue;\n        }\n\n        const match = content.match(/^\\*\\*([^*:]+)\\*\\*:\\s*(.*)$/);\n        if (match) {\n          const key = match[1].trim();\n          const val = match[2].trim();\n          metaMap[key] = val;\n        } else {\n          otherMetaLines.push(content);\n        }\n      }\n    }\n\n    // Trích xuất các trường dữ liệu chính từ metaMap\n    const code = metaMap['Mã TTHC'] || metaMap['Mã thủ tục'] || '';\n    const cap = metaMap['Cấp thực hiện'] || '';\n    const linhVuc = metaMap['Lĩnh vực'] || '';\n    const loai = metaMap['Loại thủ tục'] || 'TTHC Tiêu chuẩn';\n    const coQuanThucHien = metaMap['Cơ quan thực hiện'] || '';\n    const coQuanBanHanh = metaMap['Cơ quan ban hành'] || '';\n    const doiTuong = metaMap['Đối tượng thực hiện'] || 'Công dân, Tổ chức';\n    const mucPhi = metaMap['Mức phí'] || metaMap['Phí, lệ phí'] || '';\n    const thoiHan = metaMap['Thời hạn giải quyết'] || '';\n    const soQd = metaMap['Số Quyết định'] || '';\n    const ngayCongKhai = metaMap['Ngày công khai'] || '';\n    const ngayCapNhat = metaMap['Ngày cập nhật'] || '';\n    const ngayDieuChinh = metaMap['Ngày điều chỉnh'] || '';\n    const mucDo = metaMap['Mức độ DVCTT'] || metaMap['Mức độ'] || '';\n    const congTiepNhan = metaMap['Cổng tiếp nhận hồ sơ'] || '';\n    const linkGoc = metaMap['Link TTHC gốc'] || metaMap['Link DVC'] || '';\n\n    // Khởi tạo HTML\n    let html = '<div class=\"detail-view\">';\n\n    // 1. Tiêu đề TTHC\n    if (titleText) {\n      html += `\n        <div class=\"detail-header-block\">\n          <h2 class=\"detail-title\"><i class=\"bi bi-file-earmark-text-fill text-primary\"></i> ${escapeHtml(titleText)}</h2>\n        </div>\n      `;\n    }\n\n    // 2. Hero Summary Card (Thu gọn toàn bộ metadata dài dòng)\n    html += '<div class=\"meta-summary-card\">';\n    \n    // Badges Bar: Mã TTHC, Số QĐCB, Cấp, Lĩnh vực, Mức độ DVCTT, Phí, Loại\n    html += '<div class=\"meta-badges-bar\">';\n    if (code) {\n      html += `<span class=\"meta-pill meta-pill-code\"><i class=\"bi bi-tag-fill\"></i> ${escapeHtml(code)}</span>`;\n    }\n    if (soQd && soQd !== 'Chưa cập nhật') {\n      const soQdClean = soQd.split('(')[0].split('—')[0].replace(/`/g, '').trim();\n      if (soQdClean) {\n        html += `<button type=\"button\" class=\"meta-pill meta-pill-qdcb btn-open-qdcb-modal\" data-qdcb-id=\"${escapeHtml(soQdClean)}\" style=\"cursor:pointer;\" title=\"Bấm để xem chi tiết Quyết định công bố ${escapeHtml(soQdClean)}\"><i class=\"bi bi-file-earmark-check-fill\"></i> QĐCB: ${escapeHtml(soQdClean)}</button>`;\n      }\n    }\n    if (cap) {\n      html += `<span class=\"meta-pill meta-pill-cap\"><i class=\"bi bi-building\"></i> ${escapeHtml(cap)}</span>`;\n    }\n    if (linhVuc) {\n      html += `<span class=\"meta-pill meta-pill-field\"><i class=\"bi bi-folder-fill\"></i> ${escapeHtml(linhVuc)}</span>`;\n    }\n\n    // Pill Mức độ DVCTT\n    if (mucDo) {\n      if (mucDo.includes('Toàn trình')) {\n        html += '<span class=\"meta-pill meta-pill-dvctt-toan-trinh\"><i class=\"bi bi-check-circle-fill\"></i> Toàn trình</span>';\n      } else if (mucDo.includes('Một phần')) {\n        html += '<span class=\"meta-pill meta-pill-dvctt-mot-phan\"><i class=\"bi bi-lightning-charge-fill\"></i> Một phần</span>';\n      } else if (mucDo.includes('Chưa cung cấp') || mucDo.includes('Chưa có')) {\n        html += '<span class=\"meta-pill meta-pill-dvctt-chua\"><i class=\"bi bi-dash-circle\"></i> Chưa có DVCTT</span>';\n      } else {\n        html += `<span class=\"meta-pill meta-pill-dvctt-chua\"><i class=\"bi bi-globe2\"></i> ${escapeHtml(mucDo)}</span>`;\n      }\n    }\n\n    // Pill Mức phí tóm tắt\n    if (mucPhi) {\n      if (mucPhi.toLowerCase().includes('miễn phí') || mucPhi.includes('0 đồng') || mucPhi.includes('Không thu')) {\n        html += '<span class=\"meta-pill meta-pill-fee\" style=\"background: rgba(16, 185, 129, 0.15); color: #34d399; border-color: rgba(16, 185, 129, 0.35);\"><i class=\"bi bi-cash-stack\"></i> Miễn phí</span>';\n      } else if (mucPhi.toLowerCase().includes('có thu phí') || mucPhi.toLowerCase().includes('thu phí') || mucPhi.includes('VNĐ') || mucPhi.includes('đồng')) {\n        html += '<span class=\"meta-pill meta-pill-fee\"><i class=\"bi bi-cash-coin\"></i> Có thu phí</span>';\n      }\n    }\n\n    if (loai) {\n      html += `<span class=\"meta-pill meta-pill-type\"><i class=\"bi bi-card-checklist\"></i> ${escapeHtml(loai)}</span>`;\n    }\n    html += '</div>'; // End meta-badges-bar\n\n    // Grid 4 ô thông tin cốt lõi\n    html += '<div class=\"meta-summary-grid\">';\n    \n    if (coQuanThucHien) {\n      html += `\n        <div class=\"meta-grid-item\">\n          <i class=\"bi bi-bank meta-item-icon\"></i>\n          <div class=\"meta-item-content\">\n            <span class=\"meta-item-label\">Cơ quan thực hiện</span>\n            <span class=\"meta-item-val\">${escapeHtml(coQuanThucHien)}</span>\n          </div>\n        </div>\n      `;\n    }\n\n    if (coQuanBanHanh) {\n      html += `\n        <div class=\"meta-grid-item\">\n          <i class=\"bi bi-briefcase-fill meta-item-icon\" style=\"color: #60a5fa;\"></i>\n          <div class=\"meta-item-content\">\n            <span class=\"meta-item-label\">Cơ quan ban hành</span>\n            <span class=\"meta-item-val\">${escapeHtml(coQuanBanHanh)}</span>\n          </div>\n        </div>\n      `;\n    }\n\n    if (doiTuong) {\n      html += `\n        <div class=\"meta-grid-item\">\n          <i class=\"bi bi-people-fill meta-item-icon\" style=\"color: #c084fc;\"></i>\n          <div class=\"meta-item-content\">\n            <span class=\"meta-item-label\">Đối tượng thực hiện</span>\n            <span class=\"meta-item-val\">${escapeHtml(doiTuong)}</span>\n          </div>\n        </div>\n      `;\n    }\n\n    if (thoiHan) {\n      html += `\n        <div class=\"meta-grid-item\">\n          <i class=\"bi bi-clock-history meta-item-icon\" style=\"color: #fbbf24;\"></i>\n          <div class=\"meta-item-content\">\n            <span class=\"meta-item-label\">Thời hạn giải quyết</span>\n            <span class=\"meta-item-val\">${escapeHtml(thoiHan)}</span>\n          </div>\n        </div>\n      `;\n    } else if (mucPhi) {\n      const shortFee = mucPhi.length > 50 ? mucPhi.slice(0, 48) + '...' : mucPhi;\n      html += `\n        <div class=\"meta-grid-item\">\n          <i class=\"bi bi-cash-stack meta-item-icon\" style=\"color: #34d399;\"></i>\n          <div class=\"meta-item-content\">\n            <span class=\"meta-item-label\">Mức phí sơ bộ</span>\n            <span class=\"meta-item-val\">${escapeHtml(shortFee)}</span>\n          </div>\n        </div>\n      `;\n    }\n\n    html += '</div>'; // End meta-summary-grid\n\n    // Collapsible Details (Thu gọn các dòng Quyết định, Mốc thời gian, Chi tiết phí)\n    const hasTimeline = soQd || ngayCongKhai || ngayCapNhat || ngayDieuChinh;\n    if (hasTimeline || (mucPhi && mucPhi.length > 30)) {\n      html += `\n        <details class=\"meta-collapse-details\">\n          <summary class=\"meta-collapse-summary\">\n            <i class=\"bi bi-info-circle-fill text-primary\"></i>\n            <span>Xem thêm số quyết định, mốc thời gian & chi tiết mức phí</span>\n            <i class=\"bi bi-chevron-down collapse-icon\"></i>\n          </summary>\n          <div class=\"meta-collapse-content\">\n            ${soQd ? `<div class=\"mb-2\"><strong>Số Quyết định:</strong> ${escapeHtml(soQd)}</div>` : ''}\n            \n            ${(ngayCongKhai || ngayCapNhat || ngayDieuChinh) ? `\n              <div class=\"meta-dates-wrap\">\n                ${ngayCongKhai ? `<div class=\"meta-date-col\"><div class=\"meta-date-label\">Ngày công khai</div><div class=\"meta-date-val\">${escapeHtml(ngayCongKhai)}</div></div>` : ''}\n                ${ngayCapNhat ? `<div class=\"meta-date-col\"><div class=\"meta-date-label\">Ngày cập nhật</div><div class=\"meta-date-val\">${escapeHtml(ngayCapNhat)}</div></div>` : ''}\n                ${ngayDieuChinh ? `<div class=\"meta-date-col\"><div class=\"meta-date-label\">Ngày điều chỉnh</div><div class=\"meta-date-val\">${escapeHtml(ngayDieuChinh)}</div></div>` : ''}\n              </div>\n            ` : ''}\n\n            ${mucPhi ? `<div class=\"mt-2 pt-2\" style=\"border-top: 1px solid rgba(255,255,255,0.06);\"><strong>Chi tiết mức phí:</strong> ${escapeHtml(mucPhi)}</div>` : ''}\n          </div>\n        </details>\n      `;\n    }\n\n    // Hiển thị banner link trực tuyến nếu có\n    if (congTiepNhan) {\n      const formattedLink = congTiepNhan.replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^)]+)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"dvc-direct-link\"><i class=\"bi bi-box-arrow-up-right\"></i> $1</a>');\n      html += `\n        <div class=\"detail-dvc-banner\" style=\"background: rgba(16, 185, 129, 0.1); border-color: rgba(16, 185, 129, 0.35); margin: 12px 0 0 0;\">\n          <i class=\"bi bi-send-fill\" style=\"color: #10b981;\"></i>\n          <div class=\"dvc-banner-content\">\n            <div><strong>Cổng tiếp nhận trực tuyến:</strong> ${formattedLink}</div>\n          </div>\n        </div>\n      `;\n    }\n\n    html += '</div>'; // End meta-summary-card\n\n    // Nếu không có phần sections thì kết thúc luôn\n    if (firstSectionIdx === -1) {\n      html += '</div>';\n      return html;\n    }\n\n    // 3. Quét trước các section để tạo thanh Quick Navigation Chips\n    const sections = [];\n    let currentSec = null;\n\n    for (let i = firstSectionIdx; i < rawLines.length; i++) {\n      const line = rawLines[i].trim();\n      if (line.startsWith('## ') || line.startsWith('### ')) {\n        const isH2 = line.startsWith('## ');\n        const rawTitle = isH2 ? line.slice(3).trim() : line.slice(4).trim();\n        const secId = `detail-sec-${sections.length}`;\n\n        let icon = 'bi-info-circle-fill';\n        let shortName = rawTitle;\n\n        if (rawTitle.includes('Cách thức')) {\n          icon = 'bi-send-fill';\n          shortName = 'Cách thức';\n        } else if (rawTitle.includes('Trình tự')) {\n          icon = 'bi-diagram-3-fill';\n          shortName = 'Trình tự';\n        } else if (rawTitle.includes('Hồ sơ') || rawTitle.includes('hồ sơ')) {\n          icon = 'bi-folder2-open';\n          shortName = 'Hồ sơ';\n        } else if (rawTitle.includes('Thời hạn')) {\n          icon = 'bi-clock-history';\n          shortName = 'Thời hạn';\n        } else if (rawTitle.includes('Phí') || rawTitle.includes('phí')) {\n          icon = 'bi-cash-stack';\n          shortName = 'Phí, lệ phí';\n        } else if (rawTitle.includes('Căn cứ') || rawTitle.includes('pháp lý')) {\n          icon = 'bi-journal-bookmark-fill';\n          shortName = 'Căn cứ pháp lý';\n        } else if (rawTitle.includes('Yêu cầu') || rawTitle.includes('điều kiện')) {\n          icon = 'bi-shield-check';\n          shortName = 'Yêu cầu, ĐK';\n        } else if (rawTitle.includes('Kết quả')) {\n          icon = 'bi-award-fill';\n          shortName = 'Kết quả';\n        } else if (rawTitle.includes('HTGQ') || rawTitle.includes('HỆ THỐNG')) {\n          icon = 'bi-shield-shaded';\n          shortName = 'HTGQ Trực tuyến';\n        }\n\n        currentSec = {\n          id: secId,\n          title: rawTitle,\n          shortName,\n          icon,\n          isH2,\n          stepCount: 0,\n          docCount: 0\n        };\n        sections.push(currentSec);\n      } else if (currentSec) {\n        if (line.startsWith('**Bước ')) {\n          currentSec.stepCount++;\n        } else if (line.startsWith('- ') && currentSec.title.toLowerCase().includes('hồ sơ')) {\n          currentSec.docCount++;\n        }\n      }\n    }\n\n    // Render Quick Nav Chips\n    if (sections.length > 1) {\n      html += '<div class=\"detail-quick-nav\">';\n      sections.forEach(sec => {\n        let countText = '';\n        if (sec.stepCount > 0) countText = ` (${sec.stepCount} bước)`;\n        else if (sec.docCount > 0) countText = ` (${sec.docCount} mục)`;\n\n        html += `\n          <button type=\"button\" class=\"quick-nav-chip\" data-target=\"${sec.id}\">\n            <i class=\"bi ${sec.icon}\"></i> ${escapeHtml(sec.shortName)}${countText}\n          </button>\n        `;\n      });\n      html += '</div>';\n    }\n\n    // 4. Render nội dung từng Section Card (Collapsible)\n    let inCard = false;\n    let secCounter = 0;\n\n    for (let i = firstSectionIdx; i < rawLines.length; i++) {\n      const line = rawLines[i].trim();\n\n      if (line.startsWith('## ') || line.startsWith('### ')) {\n        if (inCard) {\n          html += '</div></div>';\n          inCard = false;\n        }\n\n        const secMeta = sections[secCounter] || { id: `detail-sec-${secCounter}` };\n        secCounter++;\n\n        const isH2 = line.startsWith('## ');\n        const sectionTitle = isH2 ? line.slice(3).trim() : line.slice(4).trim();\n        let cardClass = 'section-card collapsible';\n        let sectionIcon = 'bi-info-circle-fill';\n        let accentBorder = '';\n        let accentBg = '';\n\n        if (sectionTitle.includes('Cách thức')) {\n          cardClass += ' section-card-method';\n          sectionIcon = 'bi-send-fill';\n        } else if (sectionTitle.includes('Thời hạn')) {\n          cardClass += ' section-card-time';\n          sectionIcon = 'bi-clock-history';\n        } else if (sectionTitle.includes('Trình tự')) {\n          cardClass += ' section-card-steps';\n          sectionIcon = 'bi-diagram-3-fill';\n        } else if (sectionTitle.includes('Hồ sơ') || sectionTitle.includes('hồ sơ')) {\n          cardClass += ' section-card-docs';\n          sectionIcon = 'bi-folder2-open';\n        } else if (sectionTitle.includes('Phí') || sectionTitle.includes('phí')) {\n          cardClass += ' section-card-fee';\n          sectionIcon = 'bi-cash-stack';\n        } else if (sectionTitle.includes('Căn cứ')) {\n          cardClass += ' section-card-basis';\n          sectionIcon = 'bi-journal-bookmark-fill';\n        } else if (sectionTitle.includes('Yêu cầu') || sectionTitle.includes('điều kiện')) {\n          cardClass += ' section-card-basis';\n          sectionIcon = 'bi-shield-check';\n        } else if (sectionTitle.includes('Kết quả')) {\n          cardClass += ' section-card-result';\n          sectionIcon = 'bi-award-fill';\n        } else if (sectionTitle.includes('HTGQ') || sectionTitle.includes('HỆ THỐNG')) {\n          accentBorder = '#10b981';\n          accentBg = 'rgba(16, 185, 129, 0.06)';\n          sectionIcon = 'bi-shield-shaded';\n        }\n\n        let countBadgeHtml = '';\n        if (secMeta.stepCount > 0) {\n          countBadgeHtml = `<span class=\"section-card-count-badge\">${secMeta.stepCount} bước</span>`;\n        } else if (secMeta.docCount > 0) {\n          countBadgeHtml = `<span class=\"section-card-count-badge\">${secMeta.docCount} tài liệu</span>`;\n        }\n\n        const customStyle = accentBorder ? `style=\"border-left: 4px solid ${accentBorder}; background: ${accentBg};\"` : '';\n        const titleStyle = accentBorder ? `style=\"color: ${accentBorder};\"` : '';\n\n        html += `\n          <div class=\"${cardClass}\" id=\"${secMeta.id}\" ${customStyle}>\n            <div class=\"section-card-header-toggle\">\n              <h3 class=\"detail-section-title\" ${titleStyle}>\n                <i class=\"bi ${sectionIcon}\"></i>\n                <span>${escapeHtml(sectionTitle)}</span>\n                ${countBadgeHtml}\n              </h3>\n              <i class=\"bi bi-chevron-down toggle-chevron\"></i>\n            </div>\n            <div class=\"section-card-content\">\n        `;\n        inCard = true;\n      } else if (line.startsWith('**Bước ')) {\n        const nextLine = rawLines[i + 1]?.trim() || '';\n        html += `\n          <div class=\"step-item\">\n            <div class=\"step-name\">${escapeHtml(line.replace(/\\*\\*/g, ''))}</div>\n            ${nextLine && !nextLine.startsWith('**Bước ') && !nextLine.startsWith('### ') && !nextLine.startsWith('## ') ? `<div class=\"step-desc\">${escapeHtml(nextLine)}</div>` : ''}\n          </div>\n        `;\n        if (nextLine && !nextLine.startsWith('**Bước ') && !nextLine.startsWith('### ') && !nextLine.startsWith('## ')) i++;\n      } else if (line.startsWith('#### ')) {\n        html += `<h4 class=\"detail-subsection-title\">${escapeHtml(line.slice(5))}</h4>`;\n      } else if (line.startsWith('**') && line.endsWith('**')) {\n        html += `<h5 class=\"detail-group-label\">${escapeHtml(line.replace(/\\*\\*/g, ''))}</h5>`;\n      } else if (line.startsWith('- ')) {\n        const content = line.slice(2);\n        if (\n          content.includes('ID Hệ thống') ||\n          content.includes('ID hệ thống') ||\n          content.startsWith('**ID Hệ thống**') ||\n          content.startsWith('**ID**:') ||\n          content.startsWith('**ID**')\n        ) {\n          continue;\n        }\n\n        const formatted = content\n          .replace(/\\*\\*([^*]+)\\*\\*/g, '<strong>$1</strong>')\n          .replace(/`([^`]+)`/g, '<code>$1</code>')\n          .replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^)]+)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"dvc-direct-link\"><i class=\"bi bi-box-arrow-up-right\"></i> $1</a>');\n\n        if (content.includes('Mức độ DVCTT') || content.includes('Mức độ:')) {\n          let badgeColor = '#38bdf8';\n          let badgeBg = 'rgba(56, 189, 248, 0.12)';\n          let badgeBorder = 'rgba(56, 189, 248, 0.3)';\n          let icon = 'bi-globe2';\n\n          if (content.includes('Toàn trình')) {\n            badgeColor = '#10b981';\n            badgeBg = 'rgba(16, 185, 129, 0.12)';\n            badgeBorder = 'rgba(16, 185, 129, 0.35)';\n            icon = 'bi-check-circle-fill';\n          } else if (content.includes('Một phần')) {\n            badgeColor = '#f59e0b';\n            badgeBg = 'rgba(245, 158, 11, 0.12)';\n            badgeBorder = 'rgba(245, 158, 11, 0.35)';\n            icon = 'bi-lightning-charge-fill';\n          } else if (content.includes('Chưa cung cấp')) {\n            badgeColor = '#94a3b8';\n            badgeBg = 'rgba(148, 163, 184, 0.12)';\n            badgeBorder = 'rgba(148, 163, 184, 0.25)';\n            icon = 'bi-building';\n          }\n\n          html += `\n            <div class=\"detail-muc-do-banner\" style=\"background: ${badgeBg}; border: 1px solid ${badgeBorder}; color: ${badgeColor}; padding: 10px 14px; border-radius: 8px; margin: 8px 0 12px 0; display: flex; align-items: center; gap: 10px; font-size: 0.9rem;\">\n              <i class=\"bi ${icon}\" style=\"font-size: 1.25rem; flex-shrink: 0;\"></i>\n              <div class=\"muc-do-content\" style=\"flex: 1; color: var(--text-main);\">\n                ${formatted}\n              </div>\n            </div>\n          `;\n          continue;\n        }\n\n        if (content.includes('Cổng tiếp nhận hồ sơ')) {\n          html += `\n            <div class=\"detail-dvc-banner\" style=\"background: rgba(16, 185, 129, 0.1); border-color: rgba(16, 185, 129, 0.35); margin: 8px 0 12px 0;\">\n              <i class=\"bi bi-box-arrow-up-right\" style=\"color: #10b981;\"></i>\n              <div class=\"dvc-banner-content\">\n                <div>${formatted}</div>\n              </div>\n            </div>\n          `;\n          continue;\n        }\n\n        if (content.includes('Cổng DVC Quốc gia') || content.includes('Link TTHC gốc') || content.includes('Link DVC')) {\n          html += `\n            <div class=\"detail-dvc-banner\">\n              <i class=\"bi bi-globe2\"></i>\n              <div class=\"dvc-banner-content\">\n                <div>${formatted}</div>\n              </div>\n            </div>\n          `;\n        } else {\n          html += `<div class=\"detail-list-item\"><span class=\"list-bullet\">•</span><div class=\"list-text\">${formatted}</div></div>`;\n        }\n      } else if (line.startsWith('*') && line.endsWith('*')) {\n        html += `<p class=\"detail-note\"><em>${escapeHtml(line.slice(1, -1))}</em></p>`;\n      } else if (line) {\n        html += `<p class=\"detail-paragraph\">${escapeHtml(line)}</p>`;\n      }\n    }\n\n    if (inCard) {\n      html += '</div></div>';\n    }\n\n    html += '</div>';\n    return html;\n  }\n\n  function renderProcedureDetail(markdownText) {\n    viewportRendered.innerHTML = formatDetailHtml(markdownText);\n  }\n\n  // Tương tác Collapsible Sections & Quick Nav Chips\n  document.addEventListener('click', (e) => {\n    // 0a. Quay lại lịch sử điều hướng trong Modal\n    const backBtn = e.target.closest('.modal-back-btn');\n    if (backBtn) {\n      const prev = modalNavHistory.pop();\n      if (prev) {\n        if (prev.type === 'qdcb') openQDCBModal(prev.id, true);\n        else if (prev.type === 'tthc') openDetailModal(prev.id, true);\n      }\n      return;\n    }\n\n    // 0b. Mở Modal Chi tiết QĐCB khi click vào label QĐCB\n    const qdcbBtn = e.target.closest('.btn-open-qdcb-modal');\n    if (qdcbBtn) {\n      const qdId = qdcbBtn.dataset.qdcbId;\n      if (qdId) openQDCBModal(qdId);\n      return;\n    }\n\n    // 1. Toggle đóng/mở thẻ section card khi click header\n    const toggleHeader = e.target.closest('.section-card-header-toggle');\n    if (toggleHeader) {\n      const card = toggleHeader.closest('.section-card.collapsible');\n      if (card) {\n        card.classList.toggle('collapsed');\n      }\n      return;\n    }\n\n    // 2. Nhảy nhanh tới section khi click Quick Nav Chip\n    const navChip = e.target.closest('.quick-nav-chip');\n    if (navChip) {\n      const targetId = navChip.dataset.target;\n      if (!targetId) return;\n\n      const targetEl = document.getElementById(targetId);\n      if (targetEl) {\n        // Nếu section đang bị đóng, tự động mở ra\n        if (targetEl.classList.contains('collapsed')) {\n          targetEl.classList.remove('collapsed');\n        }\n\n        // Đánh dấu active cho chip vừa chọn\n        const parentNav = navChip.closest('.detail-quick-nav');\n        if (parentNav) {\n          parentNav.querySelectorAll('.quick-nav-chip').forEach(c => c.classList.remove('active'));\n          navChip.classList.add('active');\n        }\n\n        // Cuộn mượt tới section\n        targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });\n      }\n    }\n  });\n\n  let modalNavHistory = [];\n  let currentModalState = null;\n\n  function getModalBackBtnHtml() {\n    if (modalNavHistory.length === 0) return '';\n    return `<button type=\"button\" class=\"modal-back-btn\" title=\"Quay lại mục trước đó\"><i class=\"bi bi-arrow-left\"></i> Quay lại</button>`;\n  }\n\n  // Modal open detail\n  async function openDetailModal(code, isBack = false) {\n    if (!isBack && modal.style.display === 'flex' && currentModalState && !(currentModalState.type === 'tthc' && currentModalState.id === code)) {\n      modalNavHistory.push(currentModalState);\n    }\n    currentModalState = { type: 'tthc', id: code };\n\n    modal.style.display = 'flex';\n    currentModalMarkdown = '';\n    currentModalCode = code;\n\n    // Reset chế độ xem về Giao diện trực quan và ẩn các nút hành động khi đang tải\n    if (modalBody) modalBody.style.display = 'block';\n    if (modalMarkdownViewport) modalMarkdownViewport.style.display = 'none';\n    if (btnModalModeRendered) btnModalModeRendered.classList.add('active');\n    if (btnModalModeMarkdown) btnModalModeMarkdown.classList.remove('active');\n    if (modalViewToggle) modalViewToggle.style.display = 'none';\n    if (btnModalCopyMd) btnModalCopyMd.style.display = 'none';\n    if (btnModalDownloadMd) btnModalDownloadMd.style.display = 'none';\n\n    const initialUrl = (code && code.includes('-') && code.length > 20)\n      ? `https://dichvucong.gov.vn/thu-tuc-hanh-chinh/${encodeURIComponent(code)}`\n      : '';\n\n    modalTitle.innerHTML = `\n      ${getModalBackBtnHtml()}\n      <span>Chi tiết TTHC: ${escapeHtml(code)}</span>\n      <a href=\"${initialUrl}\" id=\"modal-dvc-link-btn\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-xs modal-dvc-badge\" title=\"Mở trang nộp hồ sơ trên Cổng Dịch vụ công Quốc gia\" style=\"${initialUrl ? '' : 'display: none;'}\">\n        <i class=\"bi bi-send-fill\"></i> Nộp hồ sơ\n      </a>\n    `;\n    modalBody.innerHTML = `\n      <div class=\"loader-container\">\n        <div class=\"spinner\"></div>\n        <p>Đang tải chi tiết hồ sơ mã ${code} từ MCP Server...</p>\n      </div>\n    `;\n\n    const apiKey = getActiveApiKey();\n    const targetUrl = apiKey\n      ? `${currentOrigin}/mcp?api-key=${encodeURIComponent(apiKey)}`\n      : `${currentOrigin}/mcp`;\n\n    try {\n      const res = await fetch(targetUrl, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({\n          jsonrpc: '2.0',\n          id: Date.now(),\n          method: 'tools/call',\n          params: {\n            name: 'tra_cuu_theo_ma_tthc',\n            arguments: { ma_tthc: code }\n          }\n        })\n      });\n\n      const data = await res.json();\n      const rawMd = data?.result?.content?.[0]?.text || 'Không tìm thấy chi tiết.';\n      const md = stripInternalIds(rawMd);\n      currentModalMarkdown = md;\n\n      // Cập nhật link DVC theo URL trực tiếp từ kết quả\n      const matchLink = md.match(/Cổng tiếp nhận hồ sơ[^:]*:\\s*\\[(?:[^\\]]*)\\]\\((https?:\\/\\/[^)]+)\\)/) ||\n                        md.match(/Link (?:TTHC gốc|DVC)[^:]*:\\s*\\[(?:[^\\]]*)\\]\\((https?:\\/\\/[^)]+)\\)/);\n      if (matchLink && matchLink[1]) {\n        const btnLink = document.getElementById('modal-dvc-link-btn');\n        if (btnLink) {\n          btnLink.href = matchLink[1];\n          btnLink.style.display = 'inline-flex';\n        }\n      }\n\n      // Trích xuất Mức độ DVCTT để gắn badge trực quan trên tiêu đề Modal\n      const matchMucDo = md.match(/\\*\\*Mức độ DVCTT\\*\\*:\\s*([^\\n\\r]+)/);\n      let mucDoPill = '';\n      if (matchMucDo && matchMucDo[1]) {\n        const txt = matchMucDo[1];\n        if (txt.includes('Toàn trình')) {\n          mucDoPill = '<span class=\"badge\" style=\"background: rgba(16, 185, 129, 0.15); color: #10b981; border: 1px solid rgba(16, 185, 129, 0.35); padding: 4px 10px; border-radius: 9999px; font-size: 0.75rem; font-weight: 600;\"><i class=\"bi bi-check-circle-fill\"></i> DVCTT Toàn trình</span>';\n        } else if (txt.includes('Một phần')) {\n          mucDoPill = '<span class=\"badge\" style=\"background: rgba(245, 158, 11, 0.15); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.35); padding: 4px 10px; border-radius: 9999px; font-size: 0.75rem; font-weight: 600;\"><i class=\"bi bi-lightning-charge-fill\"></i> DVCTT Một phần</span>';\n        } else if (txt.includes('Chưa cung cấp')) {\n          mucDoPill = '<span class=\"badge\" style=\"background: rgba(148, 163, 184, 0.15); color: #94a3b8; border: 1px solid rgba(148, 163, 184, 0.3); padding: 4px 10px; border-radius: 9999px; font-size: 0.75rem; font-weight: 600;\"><i class=\"bi bi-building\"></i> Chưa có DVCTT</span>';\n        }\n      }\n\n      // Trích xuất Số Quyết định công bố để gắn label trực quan trên tiêu đề Modal\n      const matchSoQd = md.match(/\\*\\*Số Quyết định\\*\\*:\\s*([^\\n\\r]+)/);\n      let qdcbPill = '';\n      if (matchSoQd && matchSoQd[1]) {\n        const rawQd = matchSoQd[1].trim();\n        if (rawQd && !rawQd.includes('Chưa cập nhật')) {\n          const soQdClean = rawQd.split('(')[0].split('—')[0].replace(/`/g, '').trim();\n          if (soQdClean) {\n            qdcbPill = `<button type=\"button\" class=\"meta-pill meta-pill-qdcb btn-open-qdcb-modal\" data-qdcb-id=\"${escapeHtml(soQdClean)}\" style=\"padding: 4px 10px; font-size: 0.75rem; cursor: pointer;\" title=\"Bấm để mở Modal Chi tiết QĐCB\"><i class=\"bi bi-file-earmark-check-fill\"></i> QĐCB: ${escapeHtml(soQdClean)}</button>`;\n          }\n        }\n      }\n\n      if (mucDoPill || qdcbPill) {\n        modalTitle.innerHTML = `\n          ${getModalBackBtnHtml()}\n          <span>Chi tiết TTHC: ${escapeHtml(code)}</span>\n          ${mucDoPill}\n          ${qdcbPill}\n          <a href=\"${matchLink ? matchLink[1] : initialUrl}\" id=\"modal-dvc-link-btn\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-xs modal-dvc-badge\" title=\"Mở trang nộp hồ sơ trực tuyến\" style=\"${(matchLink || initialUrl) ? '' : 'display: none;'}\">\n            <i class=\"bi bi-send-fill\"></i> Nộp hồ sơ\n          </a>\n        `;\n      }\n\n      // Render nội dung giao diện và gán mã nguồn Markdown có cấu trúc\n      modalBody.innerHTML = formatDetailHtml(md);\n      if (modalMarkdownCode) {\n        modalMarkdownCode.textContent = md;\n      }\n\n      // Kích hoạt các nút xem và xuất dữ liệu Markdown có cấu trúc\n      if (modalViewToggle) modalViewToggle.style.display = 'inline-flex';\n      if (btnModalCopyMd) btnModalCopyMd.style.display = 'inline-flex';\n      if (btnModalDownloadMd) btnModalDownloadMd.style.display = 'inline-flex';\n    } catch (err) {\n      modalBody.innerHTML = `<p style=\"color: #f43f5e;\">Lỗi tải chi tiết: ${escapeHtml(err.message)}</p>`;\n    }\n  }\n\n  // Mở Modal Chi tiết QĐCB chuẩn cấu trúc Cổng Dịch vụ công Quốc gia\n  async function openQDCBModal(idOrSoQd, isBack = false) {\n    if (!idOrSoQd) return;\n    if (!isBack && modal.style.display === 'flex' && currentModalState && !(currentModalState.type === 'qdcb' && currentModalState.id === idOrSoQd)) {\n      modalNavHistory.push(currentModalState);\n    }\n    currentModalState = { type: 'qdcb', id: idOrSoQd };\n\n    modal.style.display = 'flex';\n    currentModalMarkdown = '';\n    currentModalCode = `QDCB-${idOrSoQd}`;\n\n    if (modalBody) modalBody.style.display = 'block';\n    if (modalMarkdownViewport) modalMarkdownViewport.style.display = 'none';\n    if (btnModalModeRendered) btnModalModeRendered.classList.add('active');\n    if (btnModalModeMarkdown) btnModalModeMarkdown.classList.remove('active');\n    if (modalViewToggle) modalViewToggle.style.display = 'none';\n    if (btnModalCopyMd) btnModalCopyMd.style.display = 'none';\n    if (btnModalDownloadMd) btnModalDownloadMd.style.display = 'none';\n\n    modalTitle.innerHTML = `${getModalBackBtnHtml()}<span>Quyết định công bố: ${escapeHtml(idOrSoQd)}</span>`;\n    modalBody.innerHTML = `\n      <div class=\"loader-container\">\n        <div class=\"spinner\"></div>\n        <p>Đang tải chi tiết Quyết định công bố ${escapeHtml(idOrSoQd)}...</p>\n      </div>\n    `;\n\n    const apiKey = getActiveApiKey();\n    const keyQuery = apiKey ? `&api-key=${encodeURIComponent(apiKey)}` : '';\n\n    try {\n      const [jsonRes, mdRes] = await Promise.all([\n        fetch(`${currentOrigin}/api/qdcb/detail?id=${encodeURIComponent(idOrSoQd)}&dinh_dang=json${keyQuery}`),\n        fetch(`${currentOrigin}/api/qdcb/detail?id=${encodeURIComponent(idOrSoQd)}&dinh_dang=markdown${keyQuery}`)\n      ]);\n\n      const jsonData = await jsonRes.json();\n      const mdData = await mdRes.json();\n\n      if (!jsonData.success || !jsonData.data) {\n        modalBody.innerHTML = `<p style=\"color: #f43f5e;\">${escapeHtml(jsonData.markdown || 'Không tìm thấy Quyết định công bố.')}</p>`;\n        return;\n      }\n\n      const detail = jsonData.data;\n      currentModalMarkdown = mdData.markdown || '';\n      if (modalMarkdownCode) modalMarkdownCode.textContent = currentModalMarkdown;\n\n      const soQd = detail.so_quyet_dinh || idOrSoQd;\n      const trangThaiLabel = detail.trang_thai_label || 'Đã công bố';\n      const loaiLabel = detail.loai_quyet_dinh_label || 'Tiêu chuẩn';\n\n      modalTitle.innerHTML = `\n        ${getModalBackBtnHtml()}\n        <span>Quyết định công bố: ${escapeHtml(soQd)}</span>\n        <span class=\"badge\" style=\"background: rgba(16, 185, 129, 0.15); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.35); padding: 4px 10px; border-radius: 9999px; font-size: 0.75rem; font-weight: 600;\">\n          <i class=\"bi bi-check-circle-fill\"></i> ${escapeHtml(trangThaiLabel)}\n        </span>\n        <span class=\"badge\" style=\"background: rgba(56, 189, 248, 0.15); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.35); padding: 4px 10px; border-radius: 9999px; font-size: 0.75rem; font-weight: 600;\">\n          ${escapeHtml(loaiLabel)}\n        </span>\n        ${detail.url ? `\n        <a href=\"${escapeHtml(detail.url)}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-xs modal-dvc-badge\" title=\"Mở văn bản gốc trên Cổng DVCQG\">\n          <i class=\"bi bi-box-arrow-up-right\"></i> Xem trên DVCQG\n        </a>` : ''}\n      `;\n\n      modalBody.innerHTML = renderQDCBModalHtml(detail);\n\n      // Gắn sự kiện chuyển tab Công khai mới / Sửa đổi bổ sung / Bãi bỏ\n      const tabBtns = modalBody.querySelectorAll('.qdcb-tab-btn');\n      const tabPanels = modalBody.querySelectorAll('.qdcb-tab-panel');\n      tabBtns.forEach(btn => {\n        btn.addEventListener('click', () => {\n          const targetTab = btn.dataset.tab;\n          tabBtns.forEach(b => b.classList.remove('active'));\n          tabPanels.forEach(p => (p.style.display = p.dataset.panel === targetTab ? 'block' : 'none'));\n          btn.classList.add('active');\n        });\n      });\n\n      // Gắn sự kiện tìm kiếm nhanh bên trong bảng TTHC của QĐCB\n      const searchInput = modalBody.querySelector('.qdcb-table-search');\n      if (searchInput) {\n        searchInput.addEventListener('input', () => {\n          const q = searchInput.value.trim().toLowerCase();\n          modalBody.querySelectorAll('.qdcb-table tbody tr').forEach(row => {\n            const text = row.textContent.toLowerCase();\n            row.style.display = !q || text.includes(q) ? '' : 'none';\n          });\n        });\n      }\n\n      // Gắn sự kiện copy nhanh Số Quyết định\n      modalBody.querySelectorAll('.qdcb-copy-btn').forEach(btn => {\n        btn.addEventListener('click', async () => {\n          const val = btn.dataset.copyVal;\n          if (!val) return;\n          await navigator.clipboard.writeText(val);\n          showToast(`Đã sao chép: ${val}`);\n        });\n      });\n\n      // Gắn sự kiện Export CSV danh sách TTHC trong QĐCB\n      const btnExportCsv = modalBody.querySelector('.btn-export-qdcb-csv');\n      if (btnExportCsv) {\n        btnExportCsv.addEventListener('click', () => {\n          const rows = [['Nhóm', 'Mã TTHC', 'Tên thủ tục hành chính', 'Ngày hiệu lực', 'Trạng thái', 'URL']];\n          const tthc = detail.tthc_kem_theo || {};\n          const pushRows = (label, grp) => {\n            (grp?.items || []).forEach(it => {\n              rows.push([\n                label,\n                it.ma_tthc || '',\n                (it.ten_tthc || '').replace(/\"/g, '\"\"'),\n                it.ngay_hieu_luc || '',\n                it.trang_thai === 'INACTIVE' ? 'Đã bãi bỏ' : 'Đang công bố',\n                it.url || ''\n              ]);\n            });\n          };\n          pushRows('Công khai mới', tthc.cong_khai_moi);\n          pushRows('Sửa đổi, bổ sung', tthc.sua_doi_bo_sung);\n          pushRows('Thay thế', tthc.thay_the);\n          pushRows('Điều chỉnh', tthc.dieu_chinh);\n          pushRows('Bãi bỏ', tthc.bai_bo);\n\n          const csvContent = '\\uFEFF' + rows.map(r => r.map(c => `\"${c}\"`).join(',')).join('\\n');\n          const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });\n          const url = URL.createObjectURL(blob);\n          const a = document.createElement('a');\n          a.href = url;\n          a.download = `QDCB-${soQd.replace(/[/\\\\?%*:|\"<>]/g, '-')}.csv`;\n          document.body.appendChild(a);\n          a.click();\n          document.body.removeChild(a);\n          URL.revokeObjectURL(url);\n          showToast(`Đã xuất danh sách TTHC của ${soQd} ra CSV!`);\n        });\n      }\n\n      // Gắn sự kiện bấm vào Mã TTHC hoặc nút Xem chi tiết -> mở Modal Chi tiết TTHC\n      modalBody.querySelectorAll('.btn-qdcb-open-tthc').forEach(btn => {\n        btn.addEventListener('click', () => {\n          const tthcCode = btn.dataset.tthcCode;\n          if (tthcCode) openDetailModal(tthcCode);\n        });\n      });\n\n      if (modalViewToggle) modalViewToggle.style.display = 'inline-flex';\n      if (btnModalCopyMd) btnModalCopyMd.style.display = 'inline-flex';\n      if (btnModalDownloadMd) btnModalDownloadMd.style.display = 'inline-flex';\n    } catch (err) {\n      modalBody.innerHTML = `<p style=\"color: #f43f5e;\">Lỗi tải chi tiết QĐCB: ${escapeHtml(err.message)}</p>`;\n    }\n  }\n\n  function renderQDCBModalHtml(detail) {\n    const soQd = detail.so_quyet_dinh || 'N/A';\n    const trichYeu = detail.trich_yeu || detail.thong_tin_chi_tiet?.proposalExcerpt || 'Không có trích yếu.';\n    const coQuan = detail.co_quan_ban_hanh || 'N/A';\n    const linhVuc = Array.isArray(detail.linh_vuc) && detail.linh_vuc.length > 0 ? detail.linh_vuc.join(', ') : 'Chưa cập nhật';\n    const ngayQd = detail.ngay_quyet_dinh || 'Chưa cập nhật';\n    const ngayHieuLuc = detail.ngay_hieu_luc || ngayQd;\n    const ngayCongBo = detail.ngay_cong_bo || 'Chưa cập nhật';\n    const files = Array.isArray(detail.tep_dinh_kem) ? detail.tep_dinh_kem : [];\n    const noteText = detail.thong_tin_chi_tiet?.note || '';\n\n    const tthc = detail.tthc_kem_theo || {};\n    const cntMoi = tthc.cong_khai_moi?.count ?? (tthc.cong_khai_moi?.items?.length || 0);\n    const cntSua = tthc.sua_doi_bo_sung?.count ?? (tthc.sua_doi_bo_sung?.items?.length || 0);\n    const cntBaiBo = tthc.bai_bo?.count ?? (tthc.bai_bo?.items?.length || 0);\n    const cntThayThe = tthc.thay_the?.count ?? (tthc.thay_the?.items?.length || 0);\n    const cntDieuChinh = tthc.dieu_chinh?.count ?? (tthc.dieu_chinh?.items?.length || 0);\n    const totalTthc = cntMoi + cntSua + cntBaiBo + cntThayThe + cntDieuChinh;\n\n    const groups = [\n      { key: 'cong_khai_moi', label: 'Công khai mới', icon: 'bi-plus-circle-fill', data: tthc.cong_khai_moi },\n      { key: 'sua_doi_bo_sung', label: 'Sửa đổi, bổ sung', icon: 'bi-pencil-square', data: tthc.sua_doi_bo_sung },\n      { key: 'bai_bo', label: 'Bãi bỏ', icon: 'bi-slash-circle-fill', data: tthc.bai_bo },\n      { key: 'thay_the', label: 'Thay thế', icon: 'bi-arrow-repeat', data: tthc.thay_the },\n      { key: 'dieu_chinh', label: 'Điều chỉnh', icon: 'bi-sliders', data: tthc.dieu_chinh }\n    ].filter(g => g.key === 'cong_khai_moi' || g.key === 'sua_doi_bo_sung' || g.key === 'bai_bo' || (g.data && g.data.items && g.data.items.length > 0));\n\n    // Tự động chọn tab đầu tiên có item (> 0)\n    let activeKey = groups.find(g => g.data && g.data.items && g.data.items.length > 0)?.key || groups[0]?.key || 'cong_khai_moi';\n\n    let html = '<div class=\"qdcb-modal-view\">';\n\n    // 1. Trích yếu quyết định\n    html += `\n      <div class=\"qdcb-excerpt-box\">\n        <div class=\"qdcb-excerpt-label\"><i class=\"bi bi-file-text-fill\"></i> Trích yếu Quyết định công bố</div>\n        <div class=\"qdcb-excerpt-text\">${escapeHtml(trichYeu)}</div>\n      </div>\n    `;\n\n    // 1b. Thanh thống kê tổng quan\n    html += `\n      <div class=\"qdcb-stats-row\">\n        <span class=\"qdcb-stat-pill\"><i class=\"bi bi-collection-fill\"></i> Tổng TTHC: <strong>${totalTthc}</strong></span>\n        <span class=\"qdcb-stat-pill qdcb-stat-new\"><i class=\"bi bi-plus-circle-fill\"></i> Công khai mới: <strong>${cntMoi}</strong></span>\n        <span class=\"qdcb-stat-pill qdcb-stat-edit\"><i class=\"bi bi-pencil-square\"></i> Sửa đổi/BS: <strong>${cntSua}</strong></span>\n        <span class=\"qdcb-stat-pill qdcb-stat-drop\"><i class=\"bi bi-slash-circle-fill\"></i> Bãi bỏ: <strong>${cntBaiBo}</strong></span>\n      </div>\n    `;\n\n    // 2. Thẻ Thông tin chung (chuẩn lưới DVCQG)\n    html += `\n      <div class=\"qdcb-info-card\">\n        <div class=\"qdcb-info-grid\">\n          <div class=\"qdcb-info-cell\">\n            <span class=\"qdcb-info-label\">Số quyết định</span>\n            <span class=\"qdcb-info-val\" style=\"color:#fbbf24; font-family:var(--font-mono); display:flex; align-items:center; gap:6px;\">\n              <span>${escapeHtml(soQd)}</span>\n              <button type=\"button\" class=\"qdcb-copy-btn\" data-copy-val=\"${escapeHtml(soQd)}\" title=\"Sao chép số quyết định\"><i class=\"bi bi-clipboard\"></i></button>\n            </span>\n          </div>\n          <div class=\"qdcb-info-cell\">\n            <span class=\"qdcb-info-label\">Cơ quan ban hành</span>\n            <span class=\"qdcb-info-val\">${escapeHtml(coQuan)}</span>\n          </div>\n          <div class=\"qdcb-info-cell\">\n            <span class=\"qdcb-info-label\">Lĩnh vực</span>\n            <span class=\"qdcb-info-val\">${escapeHtml(linhVuc)}</span>\n          </div>\n          <div class=\"qdcb-info-cell\">\n            <span class=\"qdcb-info-label\">Ngày quyết định</span>\n            <span class=\"qdcb-info-val\">${escapeHtml(ngayQd)}</span>\n          </div>\n          <div class=\"qdcb-info-cell\">\n            <span class=\"qdcb-info-label\">Ngày hiệu lực</span>\n            <span class=\"qdcb-info-val\">${escapeHtml(ngayHieuLuc)}</span>\n          </div>\n          <div class=\"qdcb-info-cell\">\n            <span class=\"qdcb-info-label\">Ngày công bố</span>\n            <span class=\"qdcb-info-val\">${escapeHtml(ngayCongBo)}</span>\n          </div>\n        </div>\n        ${noteText ? `\n          <div class=\"qdcb-note-box mt-2\">\n            <i class=\"bi bi-info-circle-fill\"></i>\n            <div><strong>Ghi chú:</strong> ${escapeHtml(noteText)}</div>\n          </div>\n        ` : ''}\n        ${files.length > 0 ? `\n          <div class=\"qdcb-attachments-bar\">\n            <span class=\"qdcb-info-label\" style=\"width:100%; margin-bottom:2px;\">Tệp đính kèm:</span>\n            ${files.map(f => `<a href=\"${escapeHtml(f.url)}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"qdcb-file-btn\"><i class=\"bi bi-file-earmark-arrow-down-fill\"></i> ${escapeHtml(f.name)}</a>`).join('')}\n          </div>\n        ` : ''}\n      </div>\n    `;\n\n    // 3. Khối Danh sách TTHC thuộc Quyết định (Tabs + Toolbar tìm kiếm + Data Table chuẩn DVCQG)\n    html += '<div class=\"qdcb-tabs-section\">';\n    html += '<div class=\"qdcb-tabs-bar\">';\n    groups.forEach(g => {\n      const cnt = g.data?.count ?? (g.data?.items?.length || 0);\n      const isActive = g.key === activeKey;\n      html += `\n        <button type=\"button\" class=\"qdcb-tab-btn ${isActive ? 'active' : ''}\" data-tab=\"${g.key}\">\n          <i class=\"bi ${g.icon}\"></i>\n          <span>${escapeHtml(g.label)}</span>\n          <span class=\"qdcb-tab-count\">${cnt}</span>\n        </button>\n      `;\n    });\n    html += '</div>';\n\n    if (totalTthc > 0) {\n      html += `\n        <div class=\"qdcb-table-toolbar\">\n          <div class=\"qdcb-table-search-wrap\">\n            <i class=\"bi bi-search\"></i>\n            <input type=\"text\" class=\"qdcb-table-search\" placeholder=\"Tìm nhanh theo Mã TTHC hoặc Tên thủ tục trong quyết định này...\">\n          </div>\n          <button type=\"button\" class=\"btn btn-secondary btn-xs btn-export-qdcb-csv\" title=\"Xuất danh sách TTHC trong quyết định ra file CSV (Excel)\">\n            <i class=\"bi bi-file-earmark-spreadsheet-fill\"></i> Xuất CSV (${totalTthc})\n          </button>\n        </div>\n      `;\n    }\n\n    groups.forEach(g => {\n      const items = g.data?.items || [];\n      const isActive = g.key === activeKey;\n      html += `<div class=\"qdcb-tab-panel\" data-panel=\"${g.key}\" style=\"display: ${isActive ? 'block' : 'none'};\">`;\n\n      if (items.length === 0) {\n        html += `<div class=\"qdcb-empty-tab\"><i class=\"bi bi-inbox\" style=\"font-size:1.5rem; display:block; margin-bottom:6px;\"></i>Không có thủ tục nào trong mục ${escapeHtml(g.label)}.</div>`;\n      } else {\n        html += `\n          <div class=\"qdcb-table-wrap\">\n            <table class=\"qdcb-table\">\n              <thead>\n                <tr>\n                  <th style=\"width: 48px;\">STT</th>\n                  <th style=\"width: 120px;\">Mã TTHC</th>\n                  <th>Tên thủ tục hành chính</th>\n                  <th style=\"width: 150px;\">Lĩnh vực</th>\n                  <th style=\"width: 110px;\">Ngày hiệu lực</th>\n                  <th style=\"width: 120px;\">Trạng thái</th>\n                  <th style=\"width: 110px; text-align:right;\">Thao tác</th>\n                </tr>\n              </thead>\n              <tbody>\n                ${items.map((item, idx) => {\n                  const itemLv = Array.isArray(item.linh_vuc) && item.linh_vuc.length > 0 ? item.linh_vuc.join(', ') : linhVuc;\n                  const isInactive = item.trang_thai === 'INACTIVE';\n                  const stLabel = isInactive ? 'Đã bãi bỏ' : 'Đang công bố';\n                  const stClass = isInactive ? 'qdcb-status-inactive' : 'qdcb-status-active';\n                  const effDate = item.ngay_hieu_luc && /^\\d{4}-\\d{2}-\\d{2}/.test(item.ngay_hieu_luc)\n                    ? item.ngay_hieu_luc.slice(0, 10).split('-').reverse().join('/')\n                    : (item.ngay_hieu_luc || ngayHieuLuc);\n                  return `\n                    <tr>\n                      <td>${idx + 1}</td>\n                      <td>\n                        <button type=\"button\" class=\"qdcb-tthc-code-btn btn-qdcb-open-tthc\" data-tthc-code=\"${escapeHtml(item.ma_tthc || item.id)}\" title=\"Xem chi tiết TTHC ${escapeHtml(item.ma_tthc)}\">\n                          ${escapeHtml(item.ma_tthc || 'N/A')}\n                        </button>\n                      </td>\n                      <td style=\"font-weight: 500;\">${escapeHtml(item.ten_tthc || 'N/A')}</td>\n                      <td style=\"color: var(--text-muted); font-size:0.8rem;\">${escapeHtml(itemLv)}</td>\n                      <td style=\"white-space:nowrap;\">${escapeHtml(effDate)}</td>\n                      <td>\n                        <span class=\"qdcb-status-badge ${stClass}\">\n                          <i class=\"bi ${isInactive ? 'bi-x-circle-fill' : 'bi-check-circle-fill'}\"></i> ${stLabel}\n                        </span>\n                      </td>\n                      <td style=\"text-align:right; white-space:nowrap;\">\n                        <button type=\"button\" class=\"btn btn-primary btn-xs btn-qdcb-open-tthc\" data-tthc-code=\"${escapeHtml(item.ma_tthc || item.id)}\" title=\"Xem chi tiết thủ tục\">\n                          <i class=\"bi bi-eye\"></i> Xem\n                        </button>\n                        ${item.url ? `<a href=\"${escapeHtml(item.url)}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-secondary btn-xs\" title=\"Mở trên Cổng DVCQG\"><i class=\"bi bi-box-arrow-up-right\"></i></a>` : ''}\n                      </td>\n                    </tr>\n                  `;\n                }).join('')}\n              </tbody>\n            </table>\n          </div>\n        `;\n      }\n\n      html += '</div>';\n    });\n\n    html += '</div>'; // End qdcb-tabs-section\n    html += '</div>'; // End qdcb-modal-view\n    return html;\n  }\n\n  // Chuyển đổi chế độ xem bên trong modal (Giao diện / Markdown)\n  if (btnModalModeRendered && btnModalModeMarkdown) {\n    btnModalModeRendered.addEventListener('click', () => {\n      btnModalModeRendered.classList.add('active');\n      btnModalModeMarkdown.classList.remove('active');\n      if (modalBody) modalBody.style.display = 'block';\n      if (modalMarkdownViewport) modalMarkdownViewport.style.display = 'none';\n    });\n    btnModalModeMarkdown.addEventListener('click', () => {\n      btnModalModeMarkdown.classList.add('active');\n      btnModalModeRendered.classList.remove('active');\n      if (modalBody) modalBody.style.display = 'none';\n      if (modalMarkdownViewport) modalMarkdownViewport.style.display = 'block';\n    });\n  }\n\n  // Sao chép nội dung Markdown có cấu trúc của thủ tục\n  if (btnModalCopyMd) {\n    btnModalCopyMd.addEventListener('click', () => {\n      if (currentModalMarkdown) {\n        navigator.clipboard.writeText(currentModalMarkdown);\n        showToast(`Đã sao chép Markdown có cấu trúc của TTHC ${currentModalCode}!`);\n      }\n    });\n  }\n\n  // Xuất và tải file .md có cấu trúc đầy đủ\n  if (btnModalDownloadMd) {\n    btnModalDownloadMd.addEventListener('click', () => {\n      if (currentModalMarkdown) {\n        const cleanName = (currentModalCode || 'chi_tiet').replace(/[^a-zA-Z0-9._-]/g, '_');\n        const blob = new Blob([currentModalMarkdown], { type: 'text/markdown;charset=utf-8' });\n        const url = URL.createObjectURL(blob);\n        const a = document.createElement('a');\n        a.href = url;\n        a.download = `TTHC_${cleanName}.md`;\n        document.body.appendChild(a);\n        a.click();\n        document.body.removeChild(a);\n        URL.revokeObjectURL(url);\n        showToast(`Đã xuất tệp TTHC_${cleanName}.md thành công!`);\n      }\n    });\n  }\n\n  btnCloseModal.addEventListener('click', () => {\n    modal.style.display = 'none';\n    modalNavHistory = [];\n    currentModalState = null;\n  });\n  modal.addEventListener('click', e => {\n    if (e.target === modal) {\n      modal.style.display = 'none';\n      modalNavHistory = [];\n      currentModalState = null;\n    }\n  });\n\n  // 6. View Switcher (Rendered / Markdown / JSON)\n  btnViewRendered.addEventListener('click', () => {\n    setActiveView(btnViewRendered, viewportRendered);\n  });\n  btnViewMarkdown.addEventListener('click', () => {\n    setActiveView(btnViewMarkdown, viewportMarkdown);\n  });\n  btnViewJson.addEventListener('click', () => {\n    setActiveView(btnViewJson, viewportJson);\n  });\n\n  function setActiveView(button, viewport) {\n    [btnViewRendered, btnViewMarkdown, btnViewJson].forEach(b => b.classList.remove('active'));\n    [viewportRendered, viewportMarkdown, viewportJson].forEach(v => (v.style.display = 'none'));\n\n    button.classList.add('active');\n    viewport.style.display = 'block';\n  }\n\n  btnCopyResult.addEventListener('click', () => {\n    const textToCopy = currentMarkdownResult || JSON.stringify(currentRawResult, null, 2);\n    if (textToCopy) {\n      navigator.clipboard.writeText(textToCopy);\n      showToast('Đã sao chép kết quả!');\n    }\n  });\n\n  // 7. Client Config Generator (Tab 2)\n  clientTabs.forEach(t => {\n    t.addEventListener('click', () => {\n      clientTabs.forEach(b => b.classList.remove('active'));\n      t.classList.add('active');\n      activeClientConfig = t.dataset.client;\n      updateClientConfigs();\n    });\n  });\n\n  function updateClientConfigs() {\n    const host = currentOrigin;\n    const key = getActiveApiKey();\n    const keyParam = key ? `?api-key=${encodeURIComponent(key)}` : '?api-key=YOUR_API_KEY';\n    const sseUrl = `${host}/sse${keyParam}`;\n    const mcpUrl = `${host}/mcp${keyParam}`;\n\n    let code = '';\n    let label = '';\n\n    if (activeClientConfig === 'cursor') {\n      label = '.cursor/mcp.json';\n      code = JSON.stringify(\n        {\n          mcpServers: {\n            \"tthc-vietnam\": {\n              url: sseUrl\n            }\n          }\n        },\n        null,\n        2\n      );\n    } else if (activeClientConfig === 'claude') {\n      label = 'claude_desktop_config.json';\n      code = JSON.stringify(\n        {\n          mcpServers: {\n            \"tthc-vietnam\": {\n              url: sseUrl\n            }\n          }\n        },\n        null,\n        2\n      );\n    } else if (activeClientConfig === 'windsurf') {\n      label = '~/.codeium/windsurf/mcp_config.json';\n      code = JSON.stringify(\n        {\n          mcpServers: {\n            \"tthc-vietnam\": {\n              serverUrl: sseUrl\n            }\n          }\n        },\n        null,\n        2\n      );\n    } else if (activeClientConfig === 'openai') {\n      label = 'ChatGPT / Custom GPTs / OpenAI Actions & Plugins Guide';\n      code = JSON.stringify(\n        {\n          mcpServerEndpoint: mcpUrl,\n          mcpServerCleanEndpoint: `${host}/mcp`,\n          chatGptInstructions: {\n            step1: \"Trong GPT Builder / OpenAI Action, chọn Authentication: API Key\",\n            step2: \"Auth Type: Bearer (hoặc Custom với Header Name: X-API-Key)\",\n            step3: \"Nhập Secret Token (API Key) từ biến môi trường của bạn\",\n            step4: `Sử dụng URL Endpoint sạch: ${host}/mcp hoặc URL kèm tham số: ${mcpUrl}`\n          },\n          openAiAgentPlugins: {\n            manifestUrl: `${host}/plugin.json`,\n            mcpConfigUrl: `${host}/mcp.json`,\n            codexConfigUrl: `${host}/.mcp.json`\n          },\n          openApiActionSchema: `${host}/openapi.json`\n        },\n        null,\n        2\n      );\n    } else if (activeClientConfig === 'openapi') {\n      label = 'OpenAPI 3.1 Schema URL (Custom GPTs / Dify / n8n / Coze)';\n      code = JSON.stringify(\n        {\n          schemaUrl: `${host}/openapi.json`,\n          alternativeUrl: `${host}/schema`,\n          mcpHttpEndpoint: mcpUrl,\n          mcpSseEndpoint: sseUrl,\n          usage: \"Dán URL 'schemaUrl' vào mục Schema/OpenAPI trong Custom GPTs (Actions) hoặc Dify Tools để tự động tạo công cụ AI.\"\n        },\n        null,\n        2\n      );\n    } else if (activeClientConfig === 'curl') {\n      label = 'cURL Test Command (Direct HTTP JSON-RPC)';\n      code = `# Gọi qua tham số URL ?api-key=...\ncurl -X POST \"${mcpUrl}\" \\\\\n  -H \"Content-Type: application/json\" \\\\\n  -d '{\n    \"jsonrpc\": \"2.0\",\n    \"id\": 1,\n    \"method\": \"tools/call\",\n    \"params\": {\n      \"name\": \"tra_cuu_theo_ma_tthc\",\n      \"arguments\": {\n        \"ma_tthc\": \"6.006781\"\n      }\n    }\n  }'\n\n# Hoặc truyền qua Header \"Authorization: Bearer <key>\":\ncurl -X POST \"${host}/mcp\" \\\\\n  -H \"Authorization: Bearer ${key || 'YOUR_API_KEY'}\" \\\\\n  -H \"Content-Type: application/json\" \\\\\n  -d '{\n    \"jsonrpc\": \"2.0\",\n    \"id\": 1,\n    \"method\": \"tools/call\",\n    \"params\": {\n      \"name\": \"search\",\n      \"arguments\": {\n        \"query\": \"đăng ký kết hôn\"\n      }\n    }\n  }'`;\n    }\n\n    configFileLabel.textContent = label;\n    configCodeDisplay.textContent = code;\n  }\n\n  btnCopyConfig.addEventListener('click', () => {\n    navigator.clipboard.writeText(configCodeDisplay.textContent);\n    showToast('Đã sao chép cấu hình client!');\n  });\n\n  // 8. Quản lý tương tác Tab \"Danh Sách Tools & Schemas\" (Tìm kiếm, Bộ lọc, Sao chép, Thử ngay)\n  const inputSearchTools = document.getElementById('input-search-tools');\n  const btnClearToolSearch = document.getElementById('btn-clear-tool-search');\n  const filterChips = document.querySelectorAll('.docs-filter-chips .filter-chip');\n  const toolCards = document.querySelectorAll('.tool-doc-card');\n  const docsEmptyNotice = document.getElementById('docs-empty-notice');\n  const btnResetToolsFilter = document.getElementById('btn-reset-tools-filter');\n\n  function filterToolCards() {\n    const query = (inputSearchTools?.value || '').trim().toLowerCase();\n    const activeChip = document.querySelector('.docs-filter-chips .filter-chip.active');\n    const selectedCategory = activeChip ? activeChip.dataset.filter : 'all';\n\n    if (btnClearToolSearch) {\n      btnClearToolSearch.style.display = query ? 'flex' : 'none';\n    }\n\n    let visibleCount = 0;\n    toolCards.forEach(card => {\n      const toolName = card.dataset.tool || '';\n      const category = card.dataset.category || '';\n      const cardText = card.textContent.toLowerCase();\n\n      const matchesQuery = !query || toolName.toLowerCase().includes(query) || cardText.includes(query);\n      const matchesCategory = selectedCategory === 'all' || category === selectedCategory;\n\n      if (matchesQuery && matchesCategory) {\n        card.style.display = 'flex';\n        visibleCount++;\n      } else {\n        card.style.display = 'none';\n      }\n    });\n\n    if (docsEmptyNotice) {\n      docsEmptyNotice.style.display = visibleCount === 0 ? 'block' : 'none';\n    }\n  }\n\n  if (inputSearchTools) {\n    inputSearchTools.addEventListener('input', filterToolCards);\n  }\n\n  if (btnClearToolSearch) {\n    btnClearToolSearch.addEventListener('click', () => {\n      if (inputSearchTools) inputSearchTools.value = '';\n      filterToolCards();\n      inputSearchTools?.focus();\n    });\n  }\n\n  filterChips.forEach(chip => {\n    chip.addEventListener('click', () => {\n      filterChips.forEach(c => c.classList.remove('active'));\n      chip.classList.add('active');\n      filterToolCards();\n    });\n  });\n\n  if (btnResetToolsFilter) {\n    btnResetToolsFilter.addEventListener('click', () => {\n      if (inputSearchTools) inputSearchTools.value = '';\n      filterChips.forEach(c => {\n        if (c.dataset.filter === 'all') c.classList.add('active');\n        else c.classList.remove('active');\n      });\n      filterToolCards();\n    });\n  }\n\n  // Nút sao chép tên tool\n  document.querySelectorAll('.btn-copy-tool-name').forEach(btn => {\n    btn.addEventListener('click', async (e) => {\n      e.stopPropagation();\n      const toolName = btn.dataset.copy;\n      if (!toolName) return;\n      try {\n        await navigator.clipboard.writeText(toolName);\n        const icon = btn.querySelector('i');\n        if (icon) {\n          icon.className = 'bi bi-check-lg';\n          btn.classList.add('copied');\n          setTimeout(() => {\n            icon.className = 'bi bi-clipboard';\n            btn.classList.remove('copied');\n          }, 1500);\n        }\n        showToast(`Đã sao chép: ${toolName}`);\n      } catch (err) {\n        console.error('Lỗi sao chép:', err);\n      }\n    });\n  });\n\n  // Nút \"Thử nghiệm ngay\": tự chuyển sang tab Playground và chọn tool\n  document.querySelectorAll('.btn-try-tool').forEach(btn => {\n    btn.addEventListener('click', (e) => {\n      e.preventDefault();\n      const targetTool = btn.dataset.tool;\n      if (!targetTool) return;\n\n      const tabPlayground = document.getElementById('tab-btn-playground');\n      if (tabPlayground) {\n        tabPlayground.click();\n      }\n\n      if (selectMcpTool) {\n        selectMcpTool.value = targetTool;\n        selectMcpTool.dispatchEvent(new Event('change'));\n      }\n\n      const controlsCard = document.querySelector('.tool-controls-card');\n      if (controlsCard) {\n        controlsCard.scrollIntoView({ behavior: 'smooth', block: 'start' });\n      }\n\n      showToast(`Đã chọn công cụ ${targetTool} tại Playground!`);\n    });\n  });\n\n  // Helpers\n  function escapeHtml(str) {\n    if (!str) return '';\n    return str\n      .replace(/&/g, '&amp;')\n      .replace(/</g, '&lt;')\n      .replace(/>/g, '&gt;')\n      .replace(/\"/g, '&quot;')\n      .replace(/'/g, '&#039;');\n  }\n\n  function showToast(msg) {\n    const toast = document.createElement('div');\n    toast.className = 'toast-notification';\n    toast.textContent = msg;\n    document.body.appendChild(toast);\n    setTimeout(() => toast.classList.add('show'), 10);\n    setTimeout(() => {\n      toast.classList.remove('show');\n      setTimeout(() => toast.remove(), 300);\n    }, 2500);\n  }\n});\n";
export const EMBEDDED_LOGO_SVG: string = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" width=\"512\" height=\"512\">\n  <defs>\n    <linearGradient id=\"bgGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#DA251D\"/>\n      <stop offset=\"100%\" stop-color=\"#9B111E\"/>\n    </linearGradient>\n    <linearGradient id=\"goldGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#FFF275\"/>\n      <stop offset=\"100%\" stop-color=\"#FFD700\"/>\n    </linearGradient>\n    <filter id=\"dropShadow\" x=\"-10%\" y=\"-10%\" width=\"130%\" height=\"130%\">\n      <feDropShadow dx=\"0\" dy=\"8\" stdDeviation=\"12\" flood-color=\"#000000\" flood-opacity=\"0.35\"/>\n    </filter>\n  </defs>\n\n  <!-- Background rounded icon -->\n  <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"url(#bgGrad)\"/>\n  \n  <!-- Outer golden decorative circle -->\n  <circle cx=\"256\" cy=\"256\" r=\"210\" fill=\"none\" stroke=\"url(#goldGrad)\" stroke-width=\"8\" stroke-dasharray=\"8 6\" opacity=\"0.6\"/>\n\n  <!-- Document Plate with shadow -->\n  <rect x=\"120\" y=\"90\" width=\"272\" height=\"332\" rx=\"28\" fill=\"#FFFFFF\" filter=\"url(#dropShadow)\"/>\n\n  <!-- Document Header Banner -->\n  <path d=\"M120 118 C120 102.5 132.5 90 148 90 L364 90 C379.5 90 392 102.5 392 118 L392 170 L120 170 Z\" fill=\"url(#bgGrad)\"/>\n\n  <!-- Golden 5-point Star (Vietnam National Symbol) -->\n  <polygon points=\"256,106 266,136 298,136 272,154 282,184 256,166 230,184 240,154 214,136 246,136\" fill=\"url(#goldGrad)\"/>\n\n  <!-- Document lines representing administrative procedures -->\n  <rect x=\"160\" y=\"205\" width=\"192\" height=\"18\" rx=\"9\" fill=\"#E2E8F0\"/>\n  <rect x=\"160\" y=\"240\" width=\"150\" height=\"16\" rx=\"8\" fill=\"#CBD5E1\"/>\n  <rect x=\"160\" y=\"272\" width=\"180\" height=\"16\" rx=\"8\" fill=\"#CBD5E1\"/>\n  <rect x=\"160\" y=\"304\" width=\"130\" height=\"16\" rx=\"8\" fill=\"#CBD5E1\"/>\n\n  <!-- Verified Checkmark Badge -->\n  <circle cx=\"340\" cy=\"350\" r=\"42\" fill=\"#10B981\" filter=\"url(#dropShadow)\"/>\n  <polyline points=\"325,350 336,362 358,338\" fill=\"none\" stroke=\"#FFFFFF\" stroke-width=\"8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</svg>\n";
